/* v451 · Módulo 3 adaptado para Kids (9-11) y Teens (12-17): mismo tema y gramática, con situaciones de su mundo (sin trabajo, jefe ni dinero de adultos) */
window.MYAGE3={"young": {"t1p1": {"tip": "<p>En inglés hay dos futuros muy comunes y <b>no son intercambiables</b> en todos los casos:</p>\n<p><b>WILL</b> → predicciones basadas en tu <b>opinión o creencia</b> (<i>I think robots <b>will</b> help us at school</i>), <b>decisiones tomadas en el momento</b> (<i>Someone's at the door. — I'<b>ll</b> get it!</i>), ofrecimientos y promesas (<i>I'<b>ll</b> help you</i>).</p>\n<p><b>GOING TO</b> → predicciones con <b>evidencia presente</b>, algo que ya ves venir (<i>Look at those clouds! It'<b>s going to</b> rain</i>).</p>\n<p>Errores típicos: <i>I think it won't rain</i> suena raro; lo natural es <b>I don't think it will rain</b>. El adverbio va <b>después</b> de will y <b>antes</b> de won't: <i>She'll <b>probably</b> call</i> · <i>She <b>probably</b> won't call</i>.</p>", "vocab": [{"en": "I'll take care of it.", "es": "Yo me encargo.", "v": "f", "img": "u:photo-1507150823660-eed1895c23c7", "au": "y389e3a8e55"}, {"en": "I'll get the door.", "es": "Yo abro la puerta.", "v": "m", "img": "u:photo-1614872643157-f745e21753f5", "au": "y385dc0888b"}, {"en": "It's going to rain.", "es": "Va a llover.", "v": "f", "img": "u:photo-1599806112354-67f8b5425a06", "au": "y370045eaba"}, {"en": "I think our team will win.", "es": "Creo que nuestro equipo va a ganar.", "v": "m", "img": "u:photo-1652318694264-94cd2e2e5227", "au": "y3867c38d44"}, {"en": "That ball is going to hit the window.", "es": "Ese balón va a golpear la ventana.", "v": "f", "img": "u:photo-1646816929255-22434d57dd1a", "au": "y3ae402d2d5"}, {"en": "I'm sure you'll do great.", "es": "Estoy seguro de que te irá muy bien.", "v": "m", "img": "u:photo-1718473846668-e0f352e742b8", "au": "y34b189357d"}, {"en": "I don't think it will snow.", "es": "No creo que vaya a nevar.", "v": "f", "img": "u:photo-1593435713463-e8bf5bea9786", "au": "y301cc473e7"}, {"en": "probably / definitely", "es": "probablemente / definitivamente", "v": "m", "img": "u:photo-1599103892985-253246c5558e", "au": "y3bc6afa7cf"}], "sentences": [{"en": "Look at those clouds! It's going to rain.", "es": "¡Mira esas nubes! Va a llover.", "v": "f", "img": "u:photo-1595661671412-e20c4a3e65cc", "au": "y3210a36811"}, {"en": "I think more kids will learn online in the future.", "es": "Creo que más niños aprenderán en línea en el futuro.", "v": "m", "img": "u:photo-1495654794940-1c0cd2aeedc1", "au": "y3631354179"}, {"en": "Someone's at the door. Don't worry, I'll get it.", "es": "Alguien está en la puerta. No te preocupes, yo abro.", "v": "f", "img": "u:photo-1586059960223-6ac176e85020", "au": "y39984c1dc1"}, {"en": "He's running too fast. He's going to fall.", "es": "Va corriendo demasiado rápido. Se va a caer.", "v": "m", "img": "u:photo-1749015314315-1c193d1f67e3", "au": "y3e949e3617"}, {"en": "You'll probably feel tired after the camp.", "es": "Probablemente te sentirás cansado después del campamento.", "v": "f", "img": "u:photo-1638202951770-2240942c7d1c", "au": "y3dc625e083"}, {"en": "I promise I won't tell anyone.", "es": "Te prometo que no le diré a nadie.", "v": "m", "img": "u:photo-1621452773781-0f992fd1f5cb", "au": "y3008ed437c"}]}, "t1p2": {"tip": "<p><b>GOING TO</b> = plan o <b>intención ya decidida</b> antes de hablar: <i>I'<b>m going to</b> join the soccer team.</i></p>\n<p><b>Presente continuo</b> = plan <b>acordado con otras personas</b>, con hora/lugar: <i>We'<b>re visiting</b> Grandma at three.</i></p>\n<p><b>WILL</b> = ofrecimientos, promesas, pedidos y decisiones del momento: <i>I'<b>ll</b> call you back. <b>Will</b> you help me?</i></p>\n<p><b>Shall I / Shall we...?</b> = ofrecer o sugerir de forma amable: <i><b>Shall I</b> bring some snacks?</i></p>\n<p>⏱<b>be about to</b> = estar a punto de · <b>be likely to</b> = ser probable que.</p>", "vocab": [{"en": "I'm going to join the soccer team.", "es": "Voy a entrar al equipo de fútbol.", "v": "f", "img": "u:photo-1622659097509-4d56de14539e", "au": "y3fd33c27a7"}, {"en": "We're visiting Grandma at three.", "es": "Vamos a visitar a la abuela a las tres.", "v": "m", "img": "u:photo-1791318473641-96f7350ea630", "au": "y32b43caf24"}, {"en": "Shall I bring some snacks?", "es": "¿Quieres que lleve algo de comer?", "v": "f", "img": "u:photo-1588075592806-bbe6da990469", "au": "y3c79dbf2dc"}, {"en": "I'll call you back.", "es": "Te devuelvo la llamada.", "v": "m", "img": "u:photo-1663743629961-c6134ef1afc9", "au": "y3bc84c6dfc"}, {"en": "I'm about to leave.", "es": "Estoy a punto de salir.", "v": "f", "img": "u:photo-1551974222-1d49f576a2a4", "au": "y35c6fbec88"}, {"en": "I'm planning to learn the guitar.", "es": "Estoy planeando aprender a tocar la guitarra.", "v": "m", "img": "u:photo-1632164815269-fb4cd5ced785", "au": "y3a50a11c9f"}, {"en": "The bus is likely to be late.", "es": "Es probable que el bus llegue tarde.", "v": "f", "img": "u:photo-1768061147139-3a0a8d1bb273", "au": "y3cc461d612"}, {"en": "a New Year's resolution", "es": "un propósito de Año Nuevo", "v": "m", "img": "u:photo-1609153315697-28eeea0c02a3", "au": "y3975ebe59f"}], "sentences": [{"en": "I'm going to save my allowance for a new bike.", "es": "Voy a ahorrar mi mesada para una bicicleta nueva.", "v": "f", "img": "u:photo-1760657045486-f455ffe66b45", "au": "y330f7a112b"}, {"en": "We're flying to Orlando on Friday morning.", "es": "Vamos a volar a Orlando el viernes por la mañana.", "v": "m", "img": "u:photo-1653795163859-9ee39ecc6d62", "au": "y32d8ccae4f"}, {"en": "Shall I send you the homework tonight?", "es": "¿Quieres que te envíe la tarea esta noche?", "v": "f", "img": "u:photo-1568918460973-fe7f54f82482", "au": "y3c358c3fe9"}, {"en": "I'll help you with your project, I promise.", "es": "Te ayudaré con tu proyecto, te lo prometo.", "v": "m", "img": "u:photo-1588072432904-843af37f03ed", "au": "y3f0d3e4f71"}, {"en": "The movie is about to start. Please turn off your phones.", "es": "La película está a punto de empezar. Por favor, apaguen sus teléfonos.", "v": "f", "img": "u:photo-1489599849927-2ee91cede3ba", "au": "y39d878c8e8"}, {"en": "Are you going to try out for the school play?", "es": "¿Vas a presentarte a la audición para la obra del colegio?", "v": "m", "img": "u:photo-1786455641819-afea93f548c8", "au": "y396ef9b6f1"}]}, "t2p1": {"tip": "<p><b>Partes del cuerpo y ropa</b>: el español usa artículo, el inglés usa <b>posesivo</b>. <i>Me duele <u>la</u> cabeza</i> → <b>My</b> head hurts. <i>Se quitó <u>los</u> zapatos</i> → He took off <b>his</b> shoes.</p>\n<p>El posesivo concuerda con el <b>dueño</b>, no con la cosa: <i>Mark called <b>his</b> sister · Ana called <b>her</b> brother.</i> (en español los dos son “su”).</p>\n<p><b>its</b> = su (de una cosa/animal/equipo) · <b>it's</b> = it is / it has. <i>The team changed <b>its</b> logo. <b>It's</b> new.</i></p>\n<p><b>own</b> refuerza la posesión: <i>my <b>own</b> room · a room of my <b>own</b> · I did it <b>on my own</b></i> (solo, sin ayuda).</p>", "vocab": [{"en": "my own room", "es": "mi propio cuarto", "v": "f", "img": "u:photo-1721395288477-b546804ce392", "au": "y3a41d1ed96"}, {"en": "a bike of her own", "es": "una bicicleta propia", "v": "m", "img": "u:photo-1705643317477-86dc652ec055", "au": "y3222e94805"}, {"en": "on my own", "es": "por mi cuenta, sin ayuda", "v": "f", "img": "u:photo-1713747637207-2971748652fc", "au": "y30a36ab63d"}, {"en": "its tail", "es": "su cola (de un animal)", "v": "m", "img": "u:photo-1742407774908-c19795f6efbd", "au": "y3d54464248"}, {"en": "It's broken.", "es": "Está roto.", "v": "f", "img": "u:photo-1612933510543-5b442296703b", "au": "y3fda573dbd"}, {"en": "She broke her arm.", "es": "Se fracturó el brazo.", "v": "m", "img": "u:photo-1762347921012-79c5b5a7b9a0", "au": "y3d862369c2"}, {"en": "He shook his head.", "es": "Negó con la cabeza.", "v": "f", "img": "u:photo-1615868167768-6fe2e8eaacd8", "au": "y3bf97376be"}, {"en": "Put your hand up.", "es": "Levanta la mano.", "v": "m", "img": "u:photo-1758270704417-26c1244cfaf3", "au": "y3dffb98f10"}], "sentences": [{"en": "I finally have my own room!", "es": "¡Por fin tengo mi propio cuarto!", "v": "f", "img": "u:photo-1697162103256-dad37889d979", "au": "y3aff0a5d21"}, {"en": "Carlos hurt his knee playing soccer.", "es": "Carlos se lastimó la rodilla jugando fútbol.", "v": "m", "img": "u:photo-1713711437257-0232e837f40c", "au": "y3e44c71d82"}, {"en": "The cat is licking its paws.", "es": "El gato se está lamiendo las patas.", "v": "f", "img": "u:photo-1590564472515-1d2eb0a4a96b", "au": "y338ce4ec12"}, {"en": "Put your hands in your pockets. It's freezing!", "es": "Mete las manos en los bolsillos. ¡Hace muchísimo frío!", "v": "m", "img": "u:photo-1551280786-f0b0bf055a1d", "au": "y3b281cc06f"}, {"en": "She wants a puppy of her own.", "es": "Ella quiere un cachorro propio.", "v": "f", "img": "u:photo-1581527106934-25bc16f1d310", "au": "y3b7b54fcbb"}, {"en": "My neighbors painted their house bright blue.", "es": "Mis vecinos pintaron su casa de azul brillante.", "v": "m", "img": "u:photo-1625603736199-775425d2890a", "au": "y3c5e75e7c1"}]}, "t2p2": {"tip": "<p><b>'s</b> para personas, animales, equipos y lugares: <i>my teacher<b>'s</b> desk · the team<b>'s</b> captain · New York<b>'s</b> skyline</i>.</p>\n<p>Plural terminado en -s → solo apóstrofo: <i>my parent<b>s'</b> house</i>. Plural irregular → <b>'s</b>: <i>the children<b>'s</b> toys, women<b>'s</b> shoes</i>.</p>\n<p><b>of</b> para cosas y partes: <i>the end <b>of</b> the movie · the top <b>of</b> the page</i> (no <i>the movie's end</i>, aunque a veces se oye).</p>\n<p>⏳ Tiempo con 's: <i>a day<b>'s</b> rest · two week<b>s'</b> vacation</i>. Casa/negocio: <i>at my sister<b>'s</b></i> (= en casa de mi hermana), <i>at the dentist<b>'s</b></i>.</p>\n<p><b>Whose...?</b> = ¿De quién...?: <i><b>Whose</b> phone is this? — It's Ana<b>'s</b>.</i></p>", "vocab": [{"en": "Whose phone is this?", "es": "¿De quién es este teléfono?", "v": "f", "img": "u:photo-1585060544812-6b45742d762f", "au": "y3a025fd935"}, {"en": "my teacher's desk", "es": "el escritorio de mi profe", "v": "m", "img": "u:photo-1740635341299-3b8e3490f546", "au": "y3eee9ff2bc"}, {"en": "my parents' house", "es": "la casa de mis papás", "v": "f", "img": "u:photo-1709386263925-a4c7c8dc6f52", "au": "y3555202404"}, {"en": "the children's toys", "es": "los juguetes de los niños", "v": "m", "img": "u:photo-1598838909554-7ed3ccba096d", "au": "y3f7881a9a1"}, {"en": "the end of the movie", "es": "el final de la película", "v": "f", "img": "u:photo-1665827491450-c6f329f2285c", "au": "y3e9692ebd7"}, {"en": "the top of the page", "es": "la parte de arriba de la página", "v": "m", "img": "u:photo-1591195852468-03a01d1375d6", "au": "y31988139e9"}, {"en": "a good night's sleep", "es": "una buena noche de sueño", "v": "f", "img": "u:photo-1530455623052-e8441ae826f7", "au": "y3ee0d4f643"}, {"en": "at my sister's", "es": "en casa de mi hermana", "v": "m", "img": "u:photo-1597413545419-4013431dbfec", "au": "y39dc5a8bfa"}], "sentences": [{"en": "Whose jacket is on the back of my chair?", "es": "¿De quién es la chaqueta que está en el respaldo de mi silla?", "v": "f", "img": "u:photo-1676862450129-c2fc0a6ffd37", "au": "y3cb8356b4e"}, {"en": "We're staying at my grandparents' house in San Diego.", "es": "Nos vamos a quedar en la casa de mis abuelos en San Diego.", "v": "m", "img": "u:photo-1586498024141-1940debde48d", "au": "y3fa3956885"}, {"en": "The end of the game was really exciting.", "es": "El final del partido fue muy emocionante.", "v": "f", "img": "u:photo-1533222535026-754c501569dd", "au": "y3715212b58"}, {"en": "My cousin's dog can catch a ball in the air.", "es": "El perro de mi primo puede atrapar una pelota en el aire.", "v": "m", "img": "u:photo-1620325698009-4163b8f6d501", "au": "y384b4c8ae8"}, {"en": "I really need a good night's sleep.", "es": "De verdad necesito una buena noche de sueño.", "v": "f", "img": "u:photo-1758600588830-1bbcc78d3500", "au": "y351b38a0aa"}, {"en": "The team's new coach starts next week.", "es": "El nuevo entrenador del equipo empieza la próxima semana.", "v": "m", "img": "u:photo-1526232761682-d26e03ac148e", "au": "y34de1de64b"}]}, "t3p1": {"tip": "<p>Los <b>pronombres posesivos</b> reemplazan <b>adjetivo + sustantivo</b>: <i>This is <u>my tablet</u> → This tablet is <b>mine</b>.</i></p>\n<p>my → <b>mine</b> · your → <b>yours</b> · his → <b>his</b> · her → <b>hers</b> · our → <b>ours</b> · their → <b>theirs</b></p>\n<p><b>Nunca</b> llevan artículo ni apóstrofo: <s>the mine</s>, <s>your's</s>, <s>her's</s>. Tampoco cambian en plural: <i>These keys are <b>mine</b></i> (no <s>mines</s>).</p>\n<p><b>Whose is it?</b> / <b>Whose is this?</b> = ¿De quién es? → <i>It's <b>hers</b>.</i></p>", "vocab": [{"en": "It's mine.", "es": "Es mío.", "v": "f", "img": "u:photo-1604307974418-ba860cb35a49", "au": "y34f0aac257"}, {"en": "Is this yours?", "es": "¿Esto es tuyo?", "v": "m", "img": "u:photo-1619588321117-fca763145702", "au": "y3f2850d7fa"}, {"en": "That one is hers.", "es": "Ese es de ella.", "v": "f", "img": "u:photo-1526736068954-3d647ef94973", "au": "y32e620194a"}, {"en": "The decision is his.", "es": "La decisión es de él.", "v": "m", "img": "u:photo-1536584730280-a2af4823b80f", "au": "y3582626cad"}, {"en": "The victory is ours.", "es": "La victoria es nuestra.", "v": "f", "img": "u:photo-1540688030071-628c72ab0b08", "au": "y3660fc4ef7"}, {"en": "The dog is theirs.", "es": "El perro es de ellos.", "v": "m", "img": "u:photo-1770871821382-60ea99b0a941", "au": "y3f6fbef223"}, {"en": "Whose is it?", "es": "¿De quién es?", "v": "f", "img": "u:photo-1523362628745-0c100150b504", "au": "y3207fc0669"}, {"en": "Mine's the red one.", "es": "El mío es el rojo.", "v": "m", "img": "u:photo-1768694762075-e3ac3e6add57", "au": "y34b4a56656"}], "sentences": [{"en": "Excuse me, I think that seat is mine.", "es": "Disculpa, creo que ese asiento es mío.", "v": "f", "img": "u:photo-1764083029047-6c9b160d3554", "au": "y3e10e22533"}, {"en": "Is this charger yours or hers?", "es": "¿Este cargador es tuyo o de ella?", "v": "m", "img": "u:photo-1557767382-97b28f5488e7", "au": "y345dbcf31e"}, {"en": "Our classroom is small, but theirs is huge.", "es": "Nuestro salón es pequeño, pero el de ellos es enorme.", "v": "f", "img": "u:photo-1580582932707-520aed937b7b", "au": "y374b9bed8a"}, {"en": "Whose backpack is this? It's ours.", "es": "¿De quién es esta mochila? Es nuestra.", "v": "m", "img": "u:photo-1528384389982-64b0c3dbc32f", "au": "y3269a62ee7"}, {"en": "These crayons aren't mine. They're his.", "es": "Estos crayones no son míos. Son de él.", "v": "f", "img": "u:photo-1511288842297-6d0bc2e156c9", "au": "y31d78d3a27"}, {"en": "The choice is yours.", "es": "Tú decides.", "v": "m", "img": "u:photo-1721930878634-41c6f5f0746f", "au": "y3481e37343"}]}, "t3p2": {"tip": "<p><b>Doble posesivo</b>: <i>un amigo mío</i> = <b>a friend of mine</b> (no <s>a friend of me</s>). Igual: <i>a cousin <b>of hers</b>, a habit <b>of his</b>, this house <b>of ours</b></i>.</p>\n<p><b>Elipsis</b>: el pronombre evita repetir: <i>My bus was late, and so was <b>theirs</b>. · My phone is old. <b>Mine</b> too.</i></p>\n<p><b>Whose</b> (de quién) ≠ <b>Who's</b> (who is / who has): <i><b>Whose</b> turn is it? · <b>Who's</b> coming tonight?</i></p>\n<p>Errores típicos del hispanohablante: <s>the mine</s> → <b>mine</b> · <s>Is yours this?</s> → <b>Is this yours?</b> · <s>a friend of him</s> → <b>a friend of his</b>.</p>", "vocab": [{"en": "a cousin of hers", "es": "un primo de ella", "v": "f", "img": "u:photo-1537655780520-1e392ead81f2", "au": "y3fa053de9f"}, {"en": "an old classmate of his", "es": "un antiguo compañero de clase de él", "v": "m", "img": "u:photo-1624359689837-1d1c16599aa7", "au": "y3bcb44a9a8"}, {"en": "this house of ours", "es": "esta casa nuestra", "v": "f", "img": "u:photo-1734616048414-94ba753a46b4", "au": "y37107c7b81"}, {"en": "Who's coming?", "es": "¿Quién viene?", "v": "m", "img": "u:photo-1643376093837-e34aa74a231b", "au": "y36d43aad63"}, {"en": "Whose turn is it?", "es": "¿A quién le toca?", "v": "f", "img": "u:photo-1629760946220-5693ee4c46ac", "au": "y3c022376e6"}, {"en": "So is mine.", "es": "El mío también.", "v": "m", "img": "u:photo-1753044677341-a7a5eacb6e3f", "au": "y3286ce7431"}, {"en": "Mine too.", "es": "La mía también.", "v": "f", "img": "u:photo-1687823628233-ba2aff9f3675", "au": "y3aa57b0464"}, {"en": "Neither is ours.", "es": "El nuestro tampoco.", "v": "m", "img": "u:photo-1636837147362-4f2091789589", "au": "y3f4df30f7d"}], "sentences": [{"en": "A friend of mine just moved to Portland.", "es": "Un amigo mío se acaba de mudar a Portland.", "v": "f", "img": "u:photo-1758523671071-4e3c43d055e6", "au": "y3152bfb67d"}, {"en": "Whose turn is it to wash the dishes?", "es": "¿A quién le toca lavar los platos?", "v": "m", "img": "u:photo-1580377968109-634820edeb84", "au": "y32a6141103"}, {"en": "My bus was late, and so was theirs.", "es": "Mi bus llegó tarde, y el de ellos también.", "v": "f", "img": "u:photo-1635868357963-0a4ccaa00a9e", "au": "y357beafe43"}, {"en": "That's an old habit of his.", "es": "Esa es una vieja costumbre suya.", "v": "m", "img": "u:photo-1674649205910-ce785b24c134", "au": "y323c9e4950"}, {"en": "This little garden of ours is full of flowers.", "es": "Este jardincito nuestro está lleno de flores.", "v": "f", "img": "u:photo-1728667088041-ee116cf57c6c", "au": "y333965cad6"}, {"en": "Who's going to clean up all this?", "es": "¿Quién va a limpiar todo esto?", "v": "m", "img": "u:photo-1706889949025-2fa85aa8a5d1", "au": "y3a70c4ffb4"}]}, "t4p1": {"tip": "<p>El <b>presente perfecto</b> = <b>have / has + participio</b>: <i>I <b>have seen</b>, she <b>has tried</b></i>.</p>\n<p>Úsalo para <b>experiencias de vida</b> sin decir cuándo: <i>I'<b>ve been</b> to Mexico three times.</i> Si dices cuándo, cambia a pasado simple.</p>\n<p>Palabras clave: <b>ever</b> (alguna vez, en preguntas) · <b>never</b> (nunca) · <b>just</b> (acabar de) · <b>already</b> (ya, afirmativo) · <b>yet</b> (ya / todavía, en preguntas y negativas, al final).</p>\n<p><b>been</b> = fue y volvió · <b>gone</b> = se fue y sigue allá: <i>She's <b>been</b> to Paris</i> vs <i>She's <b>gone</b> to Paris</i>.</p>", "vocab": [{"en": "Have you ever been to Alaska?", "es": "¿Alguna vez has ido a Alaska?", "v": "f", "img": "u:photo-1581605673389-0dd8ebdf2fd2", "au": "y31a2d98291"}, {"en": "I've never tried sushi.", "es": "Nunca he probado el sushi.", "v": "m", "img": "u:photo-1617196034796-73dfa7b1fd56", "au": "y3d2586efd7"}, {"en": "She's just scored a goal.", "es": "Ella acaba de meter un gol.", "v": "f", "img": "u:photo-1629977007371-0ba395424741", "au": "y3802e5e87a"}, {"en": "I've already finished my homework.", "es": "Ya terminé mi tarea.", "v": "m", "img": "u:photo-1758612898701-e2f2958f219d", "au": "y3cbc731fd3"}, {"en": "Have you finished yet?", "es": "¿Ya terminaste?", "v": "f", "img": "u:photo-1617117206620-b01f2919ff86", "au": "y33b1ad7ffb"}, {"en": "I haven't decided yet.", "es": "Todavía no he decidido.", "v": "m", "img": "u:photo-1546458932-22b70896a584", "au": "y38c48fccbe"}, {"en": "once in a lifetime", "es": "una vez en la vida", "v": "f", "img": "u:photo-1531366936337-7c912a4589a7", "au": "y34ee9d3879"}, {"en": "to go zip-lining", "es": "hacer canopy", "v": "m", "img": "u:photo-1768350329800-3a3231d18ab3", "au": "y32c4440f1c"}], "sentences": [{"en": "Have you ever seen a whale?", "es": "¿Alguna vez has visto una ballena?", "v": "f", "img": "u:photo-1568430462989-44163eb1752f", "au": "y3b29902f69"}, {"en": "I've never seen the Grand Canyon, but it's on my list.", "es": "Nunca he visto el Gran Cañón, pero está en mi lista.", "v": "m", "img": "u:photo-1543266502-7a301a17e75e", "au": "y319ee17fb7"}, {"en": "We've just won the final!", "es": "¡Acabamos de ganar la final!", "v": "f", "img": "u:photo-1540688030071-628c72ab0b08", "au": "y3f5b72fed5"}, {"en": "Has the package arrived yet?", "es": "¿Ya llegó el paquete?", "v": "m", "img": "u:photo-1638501478003-4e9761dcfe22", "au": "y3a549f3912"}, {"en": "I've already packed my bag for camp.", "es": "Ya empaqué mi maleta para el campamento.", "v": "f", "img": "u:photo-1768214492195-c1c7f4a8f283", "au": "y394d2642d3"}, {"en": "She's gone to Chicago for a science fair.", "es": "Se fue a Chicago a una feria de ciencias.", "v": "m", "img": "u:photo-1554475901-4538ddfbccc2", "au": "y358ca21ade"}]}, "t4p2": {"tip": "<p>⏳ <b>for</b> + período (cuánto tiempo): <i>for ten years, for a long time</i> · <b>since</b> + punto de inicio: <i>since 2019, since June, since I was a kid</i>.</p>\n<p><i>Vivo aquí <u>desde hace</u> diez años / <u>Llevo</u> diez años aquí</i> → <b>I've lived here for ten years</b> (no <s>I live here for ten years</s>).</p>\n<p><b>Pasado simple</b> = tiempo <b>terminado</b> y específico: <i>yesterday, in 2018, last year, two days ago</i>.</p>\n<p><b>Presente perfecto</b> = tiempo <b>no terminado</b> o sin especificar: <i>today, this week, lately, so far</i>.</p>\n<p>Conversación típica: pregunta en presente perfecto → detalles en pasado: <i>Have you ever been to Denver? — Yes, I <b>went</b> there last spring.</i></p>", "vocab": [{"en": "I've lived here for ten years.", "es": "Vivo aquí desde hace diez años.", "v": "f", "img": "u:photo-1625603736199-775425d2890a", "au": "y3ec6f3b795"}, {"en": "She's played soccer since 2019.", "es": "Juega fútbol desde 2019.", "v": "m", "img": "u:photo-1629977007371-0ba395424741", "au": "y397f73fc74"}, {"en": "How long have you known him?", "es": "¿Cuánto tiempo hace que lo conoces?", "v": "f", "img": "u:photo-1624359689837-1d1c16599aa7", "au": "y3b40e83256"}, {"en": "I moved to Dallas in 2018.", "es": "Me mudé a Dallas en 2018.", "v": "m", "img": "u:photo-1695237724214-eec5e2d937c3", "au": "y3c225b5584"}, {"en": "We've had our dog since June.", "es": "Tenemos a nuestro perro desde junio.", "v": "f", "img": "u:photo-1740679953679-23433eaf3156", "au": "y3dd723d0bd"}, {"en": "It's been ages!", "es": "¡Ha pasado una eternidad!", "v": "m", "img": "u:photo-1768508661774-aaabc2133afe", "au": "y30e2f85c6e"}, {"en": "lately", "es": "últimamente", "v": "f", "img": "u:photo-1553729784-e91953dec042", "au": "y3df361ce53"}, {"en": "recently", "es": "recientemente", "v": "m", "img": "u:photo-1676464436590-ecf26c3572f1", "au": "y3d4618e345"}], "sentences": [{"en": "I've played the piano for almost five years.", "es": "Toco el piano desde hace casi cinco años.", "v": "f", "img": "u:photo-1552422530-9b41dc72286b", "au": "y3fcf8bc982"}, {"en": "We've known each other since first grade.", "es": "Nos conocemos desde primer grado.", "v": "m", "img": "u:photo-1569173675610-42c361a86e37", "au": "y3df83b4699"}, {"en": "I started at this school two years ago.", "es": "Empecé en este colegio hace dos años.", "v": "f", "img": "u:photo-1599725427295-6ed79ff8dbef", "au": "y38b14b8312"}, {"en": "Have you seen any good shows lately?", "es": "¿Has visto algún programa bueno últimamente?", "v": "m", "img": "u:photo-1676552053124-e8dbd747a468", "au": "y3e26421cda"}, {"en": "I've been to Denver twice. I went there last spring.", "es": "He ido a Denver dos veces. Fui la primavera pasada.", "v": "f", "img": "u:photo-1648441095877-90406e6ba04d", "au": "y3c6b049a3e"}, {"en": "How long have you had your bike?", "es": "¿Cuánto tiempo hace que tienes tu bicicleta?", "v": "m", "img": "u:photo-1566728060299-ad216d6fa3c1", "au": "y3470d2b2f3"}]}, "t5p1": {"tip": "<p>El <b>pasado perfecto</b> = <b>had + participio</b>. Sirve para hablar de una acción <b>anterior</b> a otra acción del pasado.</p>\n<p>⏪ <i>When I got to the bus stop, the bus <b>had left</b>.</i> (primero salió el bus, después llegué yo)<br>⏩ <i>When I got to the bus stop, the bus <b>left</b>.</i> (llegué y justo después salió)</p>\n<p><b>By the time</b> + pasado simple → pasado perfecto: <i>By the time the teacher arrived, the kids <b>had cleaned</b> the classroom.</i></p>\n<p>Con <b>already, just, never</b>: <i>She <b>had just</b> left. I <b>had never</b> flown before.</i></p>\n<p>Con <b>before / after</b> el orden ya es claro, así que el pasado simple también es correcto: <i>After I finished, I left.</i></p>", "vocab": [{"en": "had already left", "es": "ya se había ido", "v": "f", "img": "u:photo-1609096837711-47829e75af0f", "au": "y3a7b7bd790"}, {"en": "had never seen", "es": "nunca había visto", "v": "m", "img": "u:photo-1643664157682-e823ee08df39", "au": "y3df346ea12"}, {"en": "By the time I arrived, ...", "es": "Para cuando llegué, ...", "v": "f", "img": "u:photo-1789265176455-1c8dfe12de18", "au": "y3f41202424"}, {"en": "after I had finished", "es": "después de que había terminado", "v": "m", "img": "u:photo-1579017308347-e53e0d2fc5e9", "au": "y334b6e2e1e"}, {"en": "before the movie started", "es": "antes de que empezara la película", "v": "f", "img": "u:photo-1691480213129-106b2c7d1ee8", "au": "y387ae3b37b"}, {"en": "the bus had left", "es": "el bus había salido", "v": "m", "img": "u:photo-1613688263142-67f1e0c25ef1", "au": "y3aa83920ef"}, {"en": "I realized I had forgotten", "es": "me di cuenta de que había olvidado", "v": "f", "img": "u:photo-1645542523526-a444b4a39514", "au": "y36866235e3"}, {"en": "the battery had died", "es": "la batería se había descargado", "v": "m", "img": "u:photo-1536692192939-f1547f1cde39", "au": "y353cbb8a70"}], "sentences": [{"en": "By the time we got to the stadium, the game had already started.", "es": "Para cuando llegamos al estadio, el partido ya había empezado.", "v": "f", "img": "u:photo-1786985705341-dd7716cf1980", "au": "y33a08f6a46"}, {"en": "I had never flown on a plane before that trip.", "es": "Nunca había volado en avión antes de ese viaje.", "v": "m", "img": "u:photo-1579017976122-1109f15cf276", "au": "y377b8c1ec2"}, {"en": "When I checked my tablet, the battery had died.", "es": "Cuando revisé mi tableta, la batería se había descargado.", "v": "f", "img": "u:photo-1536692192939-f1547f1cde39", "au": "y307e409bf8"}, {"en": "She had just left when you called.", "es": "Ella acababa de salir cuando llamaste.", "v": "m", "img": "u:photo-1710969759250-20c3e0ab3160", "au": "y34da2b893d"}, {"en": "We realized we had left the tickets at home.", "es": "Nos dimos cuenta de que habíamos dejado las entradas en casa.", "v": "f", "img": "u:photo-1593871097805-09627f52f4bb", "au": "y3b234ea197"}, {"en": "After he had saved enough money, he bought a new skateboard.", "es": "Después de haber ahorrado suficiente dinero, se compró una patineta nueva.", "v": "m", "img": "u:photo-1663242930626-f1b609b595b0", "au": "y3996f9d5c7"}]}, "t5p2": {"tip": "<p>Para <b>contar una historia</b> en inglés se combinan tres tiempos:</p>\n<p><b>Pasado simple</b> = los eventos principales, en orden: <i>I <b>got</b> to the campsite and <b>set up</b> the tent.</i><br><b>Pasado continuo</b> = el fondo, lo que estaba pasando: <i>It <b>was raining</b> and everyone <b>was waiting</b>.</i><br>⏪ <b>Pasado perfecto</b> = un “flashback”, algo que pasó antes: <i>I realized I <b>had left</b> my backpack on the bus.</i></p>\n<p>Conectores narrativos: <b>It all started when</b>, <b>all of a sudden</b>, <b>meanwhile</b>, <b>then</b>, <b>unfortunately</b>, <b>luckily</b>, <b>it turned out that</b>, <b>eventually</b> (finalmente — ¡no es “eventualmente”!).</p>\n<p>No abuses del pasado perfecto: úsalo solo cuando necesites “retroceder” en la historia.</p>", "vocab": [{"en": "It all started when...", "es": "Todo empezó cuando...", "v": "f", "img": "u:photo-1517419455681-74fdb65819c4", "au": "y35796962a3"}, {"en": "At first, ...", "es": "Al principio, ...", "v": "m", "img": "u:photo-1528820713738-a43de1b61084", "au": "y34c032a97d"}, {"en": "It turned out that...", "es": "Resultó que...", "v": "f", "img": "u:photo-1713256449316-1a4067517c3b", "au": "y3faef6eff5"}, {"en": "Unfortunately, ...", "es": "Desafortunadamente, ...", "v": "m", "img": "u:photo-1763125085488-99acd00cdea7", "au": "y37111231a3"}, {"en": "eventually", "es": "finalmente", "v": "f", "img": "u:photo-1774050021227-de1f8feebcab", "au": "y388a0fa786"}, {"en": "meanwhile", "es": "mientras tanto", "v": "m", "img": "u:photo-1761839258803-21515f43190c", "au": "y3a79d6fe6f"}, {"en": "All of a sudden, ...", "es": "De repente, ...", "v": "f", "img": "u:photo-1552858725-a19e7fcd3ac4", "au": "y33c8ac7889"}, {"en": "someone had taken it", "es": "alguien se lo había llevado", "v": "m", "img": "u:photo-1789606137645-82f15956e0bd", "au": "y34b3931b8d"}], "sentences": [{"en": "It turned out that someone had taken my backpack by mistake.", "es": "Resultó que alguien se había llevado mi mochila por error.", "v": "f", "img": "u:photo-1622560481156-01fc7e1693e6", "au": "y3840c32dac"}, {"en": "When we got back to the tent, a raccoon had opened our snacks.", "es": "Cuando volvimos a la carpa, un mapache había abierto nuestra comida.", "v": "m", "img": "u:photo-1624923686627-514dd5e57bae", "au": "y3848a02433"}, {"en": "Unfortunately, I had left my jacket at school.", "es": "Desafortunadamente, había dejado mi chaqueta en el colegio.", "v": "f", "img": "u:photo-1609612840807-4cced40bdd4f", "au": "y300e7d5f2f"}, {"en": "All of a sudden, the lights went out.", "es": "De repente, se fue la luz.", "v": "m", "img": "u:photo-1565180141371-e81865da8cd0", "au": "y3125b68a72"}, {"en": "Eventually, we found a ranger who had seen our dog.", "es": "Finalmente, encontramos a un guardabosques que había visto a nuestro perro.", "v": "f", "img": "u:photo-1604916865597-83f10de2b185", "au": "y3b42a06587"}, {"en": "I didn't know that she had planned a surprise party.", "es": "No sabía que ella había planeado una fiesta sorpresa.", "v": "m", "img": "u:photo-1608790672275-309c02d888ff", "au": "y3ea716cbbd"}]}, "t6p1": {"tip": "<p>Imagina una <b>pirámide</b> de lo más preciso a lo más general:</p>\n<p>⏰ <b>AT</b> = punto exacto: <i>at 9 a.m., at noon, at night, at the moment, at Thanksgiving</i> (la temporada).<br><b>ON</b> = días y fechas: <i>on Monday, on July 4th, on my birthday, on Monday morning, on the weekend</i> (EE. UU.).<br><b>IN</b> = períodos largos: <i>in May, in 2030, in the summer, in the 1990s, in the morning</i>.</p>\n<p>Sin preposición con <b>this, next, last, every</b>: <i>I'll see you <b>next Monday</b></i> (no <s>on next Monday</s>).</p>\n<p>⏳ <b>in + período</b> = dentro de: <i>I'll call you <b>in</b> ten minutes.</i></p>\n<p><b>by</b> = fecha límite, a más tardar (<i>Hand in your homework <b>by</b> Friday</i>) · <b>until</b> = acción continua hasta ese momento (<i>I'll be at the park <b>until</b> six</i>).</p>", "vocab": [{"en": "at 8 a.m. sharp", "es": "a las 8 en punto", "v": "f", "img": "u:photo-1609775436218-78e51e5e61dd", "au": "y3ab6e8c296"}, {"en": "on Monday morning", "es": "el lunes por la mañana", "v": "m", "img": "u:photo-1761266158207-26a70892763d", "au": "y387b323aec"}, {"en": "in the summer", "es": "en el verano", "v": "f", "img": "u:photo-1588792164216-c72e6a14ae0b", "au": "y319b48b60c"}, {"en": "on the weekend", "es": "el fin de semana (EE. UU.)", "v": "m", "img": "u:photo-1759678595341-fb3d4412c55b", "au": "y38051343ee"}, {"en": "on Christmas Eve", "es": "en Nochebuena", "v": "f", "img": "u:photo-1612979168796-bcae1575b8c5", "au": "y3b1295a4bf"}, {"en": "at Thanksgiving", "es": "en (la época de) Acción de Gracias", "v": "m", "img": "u:photo-1763570645098-371723617ee9", "au": "y3109307cac"}, {"en": "in two weeks", "es": "dentro de dos semanas", "v": "f", "img": "u:photo-1787062421059-21067143ac41", "au": "y3b22416e00"}, {"en": "by Friday", "es": "para el viernes (a más tardar)", "v": "m", "img": "u:photo-1560785496-3c9d27877182", "au": "y377d500585"}], "sentences": [{"en": "The school play starts at 10 a.m. sharp.", "es": "La obra del colegio empieza a las 10 a.m. en punto.", "v": "f", "img": "u:photo-1786455641819-afea93f548c8", "au": "y316c9a0e46"}, {"en": "We usually visit my grandparents on Thanksgiving Day.", "es": "Normalmente visitamos a mis abuelos el Día de Acción de Gracias.", "v": "m", "img": "u:photo-1742696405936-fe5ef4f37b4b", "au": "y3a10b0ffe4"}, {"en": "I need to hand in my science project by Friday.", "es": "Tengo que entregar mi proyecto de ciencias para el viernes.", "v": "f", "img": "u:photo-1633828763399-e29f1cd3f4c1", "au": "y3ea5414d0b"}, {"en": "The pool is open until eight on weekends.", "es": "La piscina abre hasta las ocho los fines de semana.", "v": "m", "img": "u:photo-1563131934-4e62c674f28e", "au": "y338f676321"}, {"en": "My birthday party is on Saturday afternoon.", "es": "Mi fiesta de cumpleaños es el sábado por la tarde.", "v": "f", "img": "u:photo-1765780199629-50df915ccb18", "au": "y377c24e6cc"}, {"en": "I'll call you back in ten minutes.", "es": "Te devuelvo la llamada en diez minutos.", "v": "m", "img": "u:photo-1503324010925-71cfe52dad2a", "au": "y366afb28f6"}]}, "t6p2": {"tip": "<p>El español usa <b>“durante”</b> para todo; el inglés distingue:</p>\n<p><b>during</b> + sustantivo = <b>cuándo</b>: <i>during the class, during the flight</i>.<br>⏱️ <b>for</b> + período = <b>cuánto tiempo</b>: <i>for three hours, for a week</i>.<br><b>while</b> + sujeto + verbo: <i>while I was walking</i>.</p>\n<p><b>within</b> = dentro de un plazo máximo: <i>within 24 hours</i> · <b>from ... to / until</b> = de ... a: <i>from 9 to 5</i>.</p>\n<p><b>on time</b> = puntual (a la hora programada) · <b>in time</b> = con tiempo suficiente, antes de que sea tarde: <i>We got there just <b>in time</b> for dinner.</i></p>\n<p><b>at the end of</b> = al final de algo (momento) · <b>in the end</b> = finalmente, después de todo.</p>", "vocab": [{"en": "during the class", "es": "durante la clase", "v": "f", "img": "u:photo-1509062522246-3755977927d7", "au": "y34e94159c1"}, {"en": "for three hours", "es": "durante tres horas", "v": "m", "img": "u:photo-1594913495702-0872744c6968", "au": "y386485a9c0"}, {"en": "while I was walking", "es": "mientras caminaba", "v": "f", "img": "u:photo-1597954825943-c698d0e0869b", "au": "y37e70a94a7"}, {"en": "within 24 hours", "es": "en un plazo de 24 horas", "v": "m", "img": "u:photo-1624969862293-b749659ccc4e", "au": "y3e3e1110e5"}, {"en": "from 7 to 3", "es": "de 7 a 3", "v": "f", "img": "u:photo-1577896851231-70ef18881754", "au": "y3ac31669ef"}, {"en": "on time", "es": "puntual, a la hora exacta", "v": "m", "img": "u:photo-1583508805133-8fd03a9916d4", "au": "y312588886c"}, {"en": "in time", "es": "a tiempo, con margen", "v": "f", "img": "u:photo-1578496780896-7081cc23c111", "au": "y35a26f616d"}, {"en": "at the end of the game", "es": "al final del partido", "v": "m", "img": "u:photo-1652318694264-94cd2e2e5227", "au": "y3fb6e493b2"}], "sentences": [{"en": "My phone rang during the math test. So embarrassing!", "es": "Mi celular sonó durante el examen de matemáticas. ¡Qué vergüenza!", "v": "f", "img": "u:photo-1557989048-03456d01a26e", "au": "y3aabe61b7e"}, {"en": "We were stuck in traffic for two hours.", "es": "Estuvimos atascados en el tráfico por dos horas.", "v": "m", "img": "u:photo-1602951172321-fe0aa8865e6b", "au": "y39106f67b5"}, {"en": "I listened to music while I was walking the dog.", "es": "Escuché música mientras paseaba al perro.", "v": "f", "img": "u:photo-1618946019619-9d7b7d86b48f", "au": "y3f4ec27666"}, {"en": "Please answer the party invitation within three days.", "es": "Por favor responde la invitación a la fiesta en un plazo de tres días.", "v": "m", "img": "u:photo-1764385827792-0d3682a416de", "au": "y3eea8b2187"}, {"en": "The bus left on time, and we got home just in time for dinner.", "es": "El bus salió puntual y llegamos a casa justo a tiempo para la cena.", "v": "f", "img": "u:photo-1578496780896-7081cc23c111", "au": "y3442d98089"}, {"en": "We argued for an hour, but in the end we picked a movie.", "es": "Discutimos una hora, pero al final escogimos una película.", "v": "m", "img": "u:photo-1665827491450-c6f329f2285c", "au": "y36272e26c8"}]}, "t7p1": {"tip": "<p><b>AT</b> = un punto, o un lugar por su función: <i>at the airport, at school, at the door, at 25 Main Street</i> (dirección exacta).<br><b>IN</b> = dentro de un espacio: <i>in the elevator, in Chicago, in the car, in a taxi</i>.<br><b>ON</b> = superficie, pisos, calles (EE. UU.) y transporte público: <i>on the 5th floor, on Main Street, on the bus, on a plane</i>.</p>\n<p>Movimiento y posición:<br><b>across</b> = de un lado al otro · <b>along</b> = siguiendo una línea (río, calle, playa) · <b>through</b> = por dentro de (túnel, bosque) · <b>opposite</b> = enfrente · <b>near</b> = cerca de.</p>\n<p>Ojo: <b>in</b> a car / a taxi (no puedes caminar dentro) · <b>on</b> a bus / train / plane (sí puedes).</p>", "vocab": [{"en": "at the airport", "es": "en el aeropuerto", "v": "f", "img": "u:photo-1763618769707-3e318c25325f", "au": "y3eea0d1e8c"}, {"en": "in the elevator", "es": "en el ascensor", "v": "m", "img": "u:photo-1746702475459-89ff401cafd8", "au": "y320e362a82"}, {"en": "on the 5th floor", "es": "en el quinto piso", "v": "f", "img": "u:photo-1545324418-cc1a3fa10c00", "au": "y34a8a754c0"}, {"en": "on the bus", "es": "en el bus", "v": "m", "img": "u:photo-1503676685182-2531a01b5b5c", "au": "y3fd186d45f"}, {"en": "across the river", "es": "al otro lado del río", "v": "f", "img": "u:photo-1608237963573-ba0790bc6404", "au": "y369fab81a4"}, {"en": "along the beach", "es": "a lo largo de la playa", "v": "m", "img": "u:photo-1600712961777-07241c147be0", "au": "y3db39b1ba4"}, {"en": "through the tunnel", "es": "a través del túnel", "v": "f", "img": "u:photo-1553076067-178b5b282ef9", "au": "y38bd720904"}, {"en": "opposite the library", "es": "enfrente de la biblioteca", "v": "m", "img": "u:photo-1682854494783-bd851a8c4c62", "au": "y35e10a338c"}], "sentences": [{"en": "I'm at the airport, but my suitcase is still in Chicago.", "es": "Estoy en el aeropuerto, pero mi maleta sigue en Chicago.", "v": "f", "img": "u:photo-1569512850669-7baa648e82d8", "au": "y36a48c87d0"}, {"en": "Our classroom is on the second floor, opposite the library.", "es": "Nuestro salón está en el segundo piso, enfrente de la biblioteca.", "v": "m", "img": "u:photo-1779682663979-df3179ce580d", "au": "y3911eac342"}, {"en": "We walked across the Brooklyn Bridge at sunset.", "es": "Cruzamos el puente de Brooklyn al atardecer.", "v": "f", "img": "u:photo-1477882244523-716124bf91a1", "au": "y3f1be2864b"}, {"en": "There's a bike path along the river.", "es": "Hay una ciclovía a lo largo del río.", "v": "m", "img": "u:photo-1755789539502-b6f6f9adb6f7", "au": "y32f9530dc9"}, {"en": "The school bus goes through a long tunnel.", "es": "El bus del colegio pasa por un túnel largo.", "v": "f", "img": "u:photo-1649671965833-38b379efee55", "au": "y3c42e5de80"}, {"en": "Get in the car. We're late for school!", "es": "¡Súbete al carro! Vamos tarde al colegio.", "v": "m", "img": "u:photo-1756142008330-87dc106322a4", "au": "y3baec4ec4b"}]}, "t7p2": {"tip": "<p>Para dar direcciones usa el <b>imperativo</b>: <i><b>Go</b> straight, <b>turn</b> left, <b>cross</b> the street, <b>take</b> the second right.</i></p>\n<p>Frases preposicionales clave: <i><b>on the corner of</b> Main and 2nd · <b>across from</b> (= opposite, muy americano) · <b>next to</b> · <b>between</b> X and Y · <b>in front of</b> · <b>behind</b> · <b>at the end of</b> the street · <b>around the corner</b></i>.</p>\n<p><b>on</b> + calle (<i>on Elm Street</i>) · <b>at</b> + dirección exacta (<i>at 350 Fifth Avenue</i>).</p>\n<p>Para preguntar de forma amable: <i>Excuse me, <b>could you tell me how to get to</b> ...? · <b>Is there a</b> pharmacy <b>around here</b>?</i></p>", "vocab": [{"en": "Go straight for two blocks.", "es": "Sigue derecho dos cuadras.", "v": "f", "img": "u:photo-1660415259719-cea8eb7ac26c", "au": "y35f3936ba2"}, {"en": "Turn left on Main Street.", "es": "Gira a la izquierda en Main Street.", "v": "m", "img": "u:photo-1582211713340-dec9934f6b48", "au": "y37c4c48a2c"}, {"en": "It's on your right.", "es": "Está a tu derecha.", "v": "f", "img": "u:photo-1612012060786-58a0bf29474c", "au": "y39fb3629e9"}, {"en": "at the intersection", "es": "en la intersección", "v": "m", "img": "u:photo-1623173651777-e013ac17e563", "au": "y3f73787494"}, {"en": "right across from the park", "es": "justo enfrente del parque", "v": "f", "img": "u:photo-1708924908152-aa8df3576b86", "au": "y36cf24d510"}, {"en": "next to the ice cream shop", "es": "al lado de la heladería", "v": "m", "img": "u:photo-1567206563064-6f60f40a2b57", "au": "y3faada5b4b"}, {"en": "between Fifth and Sixth Avenue", "es": "entre la Quinta y la Sexta Avenida", "v": "f", "img": "u:photo-1663340549279-ad59ab0751fd", "au": "y398fa8fcbf"}, {"en": "at the end of the street", "es": "al final de la calle", "v": "m", "img": "u:photo-1784854519200-8ba4da39d703", "au": "y3a097528f2"}], "sentences": [{"en": "Excuse me, could you tell me how to get to the museum?", "es": "Disculpe, ¿podría decirme cómo llegar al museo?", "v": "f", "img": "u:photo-1544365712-91cd4904cd07", "au": "y37928acd95"}, {"en": "Go straight for three blocks and turn right on Elm Street.", "es": "Sigue derecho tres cuadras y gira a la derecha en Elm Street.", "v": "m", "img": "u:photo-1708685889314-013b9afd452f", "au": "y37f5aa1f05"}, {"en": "The library is on the corner of Main and 2nd.", "es": "La biblioteca está en la esquina de Main con la 2.ª.", "v": "f", "img": "u:photo-1791911827640-28fd88ae330e", "au": "y36ef4b0e48"}, {"en": "There's an ice cream shop right across from the park.", "es": "Hay una heladería justo enfrente del parque.", "v": "m", "img": "u:photo-1668209190766-fe943ac89f66", "au": "y337badbb98"}, {"en": "The museum is between the library and City Hall.", "es": "El museo está entre la biblioteca y la alcaldía.", "v": "f", "img": "u:photo-1636556602097-2435ad5198ef", "au": "y3f6c752695"}, {"en": "It's just around the corner. You can't miss it.", "es": "Está a la vuelta de la esquina. No tiene pérdida.", "v": "m", "img": "u:photo-1744725088646-0499922f6375", "au": "y3a043ae366"}]}, "t8p1": {"tip": "<p>Ya sabes decir <i>bigger</i> o <i>more expensive</i>. Ahora vas a decir <b>cuánta</b> diferencia hay.</p>\n<p>⬆️ <b>Diferencia grande</b>: <b>much / far / a lot</b> + comparativo → <i>My new school is <b>far</b> bigger than my old one.</i><br>\n↗️ <b>Diferencia pequeña</b>: <b>a bit / a little / slightly</b> + comparativo → <i>This backpack is <b>slightly</b> lighter.</i></p>\n<p><b>Igualdad</b>: <b>(just) as + adjetivo + as</b> → <i>The bus is <b>just as fast as</b> the train.</i><br>\n<b>Desigualdad</b>: <b>not as … as</b> → <i>Math is<b>n't as hard as</b> science for me.</i></p>\n<p><b>Multiplicar</b>: <b>twice / three times as … as</b> → <i>Our new house is <b>twice as big as</b> the old one.</i></p>\n<p>Nunca digas <s>very bigger</s> ni <s>more cheaper</s>: <b>very</b> no va con comparativos y no se duplica el comparativo.</p>", "vocab": [{"en": "much more expensive", "es": "mucho más caro", "v": "f", "img": "u:photo-1612036781124-847f8939b154", "au": "y37ff6e82c2"}, {"en": "far more fun", "es": "muchísimo más divertido", "v": "m", "img": "u:photo-1626234736261-f50c9ff94bef", "au": "y3ae99ae3e9"}, {"en": "a bit cheaper", "es": "un poco más barato", "v": "f", "img": "u:photo-1741389544696-0750a7ac6bbb", "au": "y3fd8fe88cc"}, {"en": "slightly bigger", "es": "ligeramente más grande", "v": "m", "img": "u:photo-1599896375807-cf6cf2932e7d", "au": "y315b6ee8d9"}, {"en": "much faster", "es": "mucho más rápido", "v": "f", "img": "u:photo-1451481454041-104482d8e284", "au": "y36d74f01fa"}, {"en": "a lot more exciting", "es": "mucho más emocionante", "v": "m", "img": "u:photo-1627035983655-0ceec61bb733", "au": "y39fe33ed64"}, {"en": "just as good as", "es": "igual de bueno que", "v": "f", "img": "u:photo-1571997478779-2adcbbe9ab2f", "au": "y3b86f9d1b7"}, {"en": "not as crowded as", "es": "no tan lleno como", "v": "m", "img": "u:photo-1520942702018-0862200e6873", "au": "y3e6881e047"}], "sentences": [{"en": "My new school is much bigger than my old one.", "es": "Mi nuevo colegio es mucho más grande que el anterior.", "v": "f", "img": "u:photo-1591123120675-6f7f1aae0e5b", "au": "y3d1b1ebc46"}, {"en": "This backpack is slightly lighter than the old one.", "es": "Esta mochila es un poco más liviana que la vieja.", "v": "m", "img": "u:photo-1594608661623-aa0bd3a69d98", "au": "y3751d94c65"}, {"en": "Flying is far faster than going by bus.", "es": "Volar es muchísimo más rápido que ir en bus.", "v": "f", "img": "u:photo-1569629743817-70d8db6c323b", "au": "y3407a160ff"}, {"en": "The beach isn't as crowded as the pool today.", "es": "La playa no está tan llena como la piscina hoy.", "v": "m", "img": "u:photo-1468879823303-35edd50416dc", "au": "y3da7578bca"}, {"en": "My cousin's dog is twice as big as mine.", "es": "El perro de mi primo es el doble de grande que el mío.", "v": "f", "img": "u:photo-1787865509592-3c16d212fd6d", "au": "y38f434649c"}, {"en": "Online games can be just as fun as board games.", "es": "Los juegos en línea pueden ser igual de divertidos que los juegos de mesa.", "v": "m", "img": "u:photo-1629760946220-5693ee4c46ac", "au": "y3a5127bd8b"}]}, "t8p2": {"tip": "<p><b>The + comparativo …, the + comparativo …</b> = <i>cuanto más …, más …</i><br>\n<i><b>The more</b> you practice, <b>the more confident</b> you become.</i> · <i><b>The sooner, the better.</b></i></p>\n<p><b>Comparativo doble</b> = algo que cambia poco a poco (<i>cada vez más</i>):<br>\n<i>bigger <b>and</b> bigger</i> · <i><b>more and more</b> popular</i> · <i>worse and worse</i></p>\n<p><b>Superlativo + present perfect</b> = experiencias de toda la vida:<br>\n<i>It's <b>the best</b> pizza <b>I've ever had</b>.</i> · <i>the <b>most</b> beautiful place <b>I've ever seen</b></i></p>\n<p>Para reforzar el superlativo: <b>by far the …</b> (de lejos) · <b>one of the …</b> + plural · <b>the second / third largest</b> · <b>the least</b> (el menos).</p>", "vocab": [{"en": "the more, the better", "es": "cuanto más, mejor", "v": "f", "img": "u:photo-1645730826845-cd2ddec9984f", "au": "y31d4ef2390"}, {"en": "the sooner, the better", "es": "cuanto antes, mejor", "v": "m", "img": "u:photo-1761697231227-c35af9a62b0a", "au": "y3adf87be29"}, {"en": "by far the best", "es": "de lejos el mejor", "v": "f", "img": "u:photo-1578269174936-2709b6aeb913", "au": "y33a3685a19"}, {"en": "the best I've ever had", "es": "el mejor que he probado", "v": "m", "img": "u:photo-1691158440000-215d7326a258", "au": "y3d2ae6f780"}, {"en": "the worst I've ever seen", "es": "el peor que he visto", "v": "f", "img": "u:photo-1433863448220-78aaa064ff47", "au": "y3d32124990"}, {"en": "one of the most popular", "es": "uno de los más populares", "v": "m", "img": "u:photo-1777489689168-497290f235d5", "au": "y320c36c1e8"}, {"en": "the least boring", "es": "el menos aburrido", "v": "f", "img": "u:photo-1524503033411-c9566986fc8f", "au": "y3a04c4ae52"}, {"en": "bigger and bigger", "es": "cada vez más grande", "v": "m", "img": "u:photo-1551945326-df678a97c3af", "au": "y3400072398"}], "sentences": [{"en": "The more you practice, the more confident you become.", "es": "Cuanto más practicas, más seguro te vuelves.", "v": "f", "img": "u:photo-1552422530-9b41dc72286b", "au": "y32feff9428"}, {"en": "This is by far the best pizza I've ever had.", "es": "Esta es de lejos la mejor pizza que he comido.", "v": "m", "img": "u:photo-1779832291336-bdd93c5d0bcd", "au": "y311c7fed34"}, {"en": "Video games are getting more and more popular.", "es": "Los videojuegos son cada vez más populares.", "v": "f", "img": "u:photo-1554410637-1a8267402b57", "au": "y37688c54d7"}, {"en": "It was the hardest test I've ever had.", "es": "Fue el examen más difícil que he tenido.", "v": "m", "img": "u:photo-1534644107580-3a4dbd494a95", "au": "y3fe82d9e1a"}, {"en": "The sooner we finish our homework, the sooner we can play.", "es": "Cuanto antes terminemos la tarea, antes podemos jugar.", "v": "f", "img": "u:photo-1554721299-e0b8aa7666ce", "au": "y354c5863bb"}, {"en": "It's one of the most interesting museums I've ever visited.", "es": "Es uno de los museos más interesantes que he visitado.", "v": "m", "img": "u:photo-1773517350296-32910edea139", "au": "y32aa2946e8"}]}, "t9p1": {"tip": "<p><b>used to + verbo base</b> = algo que <b>solía</b> pasar o ser, y <b>ya no</b> es así.<br>\n<i>I <b>used to live</b> in Chicago.</i> (Ya no vivo allá.)</p>\n<p>Negativa: <b>didn't use to</b> (¡sin <i>-d</i>!) → <i>She <b>didn't use to</b> like broccoli.</i><br>\nPregunta: <b>Did you use to …?</b> → <i><b>Did you use to</b> play sports?</i></p>\n<p><b>would + verbo</b> también describe <b>acciones repetidas</b> del pasado (muy común al contar recuerdos):<br>\n<i>Every summer we <b>would</b> go to the lake.</i></p>\n<p>Con <b>estados</b> (live, have, be, own, know, like) solo se usa <b>used to</b>:<br>\n<i>I used to have a dog.</i> · <s>I would have a dog.</s></p>\n<p><b>no longer</b> (formal, antes del verbo) = <b>not … anymore</b> (al final): <i>I <b>no longer</b> watch cartoons.</i> = <i>I do<b>n't</b> watch cartoons <b>anymore</b>.</i></p>", "vocab": [{"en": "used to live", "es": "solía vivir", "v": "f", "img": "u:photo-1593579329655-d4ebec1d4c94", "au": "y36e1df22c8"}, {"en": "didn't use to", "es": "no solía", "v": "m", "img": "u:photo-1783995343969-81469ffcae6e", "au": "y34ea8f6e1d"}, {"en": "Did you use to …?", "es": "¿Solías …?", "v": "f", "img": "u:photo-1528569937393-ee892b976859", "au": "y3cf0516bf5"}, {"en": "would spend hours", "es": "pasaba horas (solía pasar)", "v": "m", "img": "u:photo-1587654780291-39c9404d746b", "au": "y3ca9b42e3a"}, {"en": "back in the day", "es": "en aquellos tiempos", "v": "f", "img": "u:photo-1624347443725-dac2bcc04c82", "au": "y3cf8313069"}, {"en": "when I was little", "es": "cuando era pequeño", "v": "m", "img": "u:photo-1484820540004-14229fe36ca4", "au": "y3832465c2f"}, {"en": "payphone", "es": "teléfono público", "v": "f", "img": "u:photo-1525598912003-663126343e1f", "au": "y3b44fc86c6"}, {"en": "watch cartoons", "es": "ver dibujos animados", "v": "m", "img": "u:photo-1676552053124-e8dbd747a468", "au": "y3a8cfff8fa"}], "sentences": [{"en": "I used to live in Chicago, but now I live in Dallas.", "es": "Antes vivía en Chicago, pero ahora vivo en Dallas.", "v": "f", "img": "u:photo-1563718944-758794a56b34", "au": "y3d833a5be6"}, {"en": "We would spend every summer at my grandparents' farm.", "es": "Pasábamos todos los veranos en la granja de mis abuelos.", "v": "m", "img": "u:photo-1605032746765-7f7169e5e045", "au": "y3f6bfd8f96"}, {"en": "She didn't use to like broccoli, but now she loves it.", "es": "Antes no le gustaba el brócoli, pero ahora le encanta.", "v": "f", "img": "u:photo-1633859253234-d0832f649800", "au": "y396b3dbfbe"}, {"en": "Did you use to play with toy cars when you were little?", "es": "¿Jugabas con carritos cuando eras pequeño?", "v": "m", "img": "u:photo-1778587615149-b5bd97a61b31", "au": "y38fd2646d2"}, {"en": "People used to buy DVDs; nowadays they stream movies.", "es": "La gente compraba DVD; hoy en día ve películas por streaming.", "v": "f", "img": "u:photo-1665827491450-c6f329f2285c", "au": "y3580662c16"}, {"en": "My dad would always tell us stories before bed.", "es": "Mi papá siempre nos contaba historias antes de dormir.", "v": "m", "img": "u:photo-1758687126981-417a59c589a9", "au": "y3e5a0c99fe"}]}, "t9p2": {"tip": "<p>¡Cuidado! <b>used to</b> (solía) ≠ <b>be used to</b> (estar acostumbrado).</p>\n<p><b>be used to + sustantivo / verbo-ING</b> = estar acostumbrado (un <b>estado</b>):<br>\n<i>I'<b>m used to getting</b> up early.</i> · <i>She <b>isn't used to</b> the cold.</i></p>\n<p><b>get used to + sustantivo / verbo-ING</b> = acostumbrarse (un <b>proceso</b>):<br>\n<i>You'll <b>get used to</b> it.</i> · <i>I'm <b>getting used to wearing</b> braces.</i> · <i>It took me a year to <b>get used to</b> my new school.</i></p>\n<p>Aquí <b>to</b> es una preposición, por eso va <b>-ing</b>: <s>I'm used to study</s> → <i>I'm used to study<b>ing</b></i>.</p>\n<p>Funciona en todos los tiempos: <i>I <b>was</b> used to …</i> · <i>I'<b>ll get</b> used to …</i> · <i>I'<b>ve gotten</b> used to …</i></p>", "vocab": [{"en": "be used to getting up early", "es": "estar acostumbrado a madrugar", "v": "f", "img": "u:photo-1741202138198-b3d676656f7c", "au": "y3c5cdc364a"}, {"en": "get used to the cold", "es": "acostumbrarse al frío", "v": "m", "img": "u:photo-1768087038176-76d822849575", "au": "y33263d4395"}, {"en": "I'm not used to it", "es": "no estoy acostumbrado", "v": "f", "img": "u:photo-1651796699697-d04554725195", "au": "y32065cb95d"}, {"en": "I'm getting used to it", "es": "me estoy acostumbrando", "v": "m", "img": "u:photo-1630864972901-052dfdc7fba4", "au": "y30bb357af2"}, {"en": "culture shock", "es": "choque cultural", "v": "f", "img": "u:photo-1700637471746-6c63fc27571e", "au": "y321dfd1c8c"}, {"en": "adjust to", "es": "adaptarse a", "v": "m", "img": "u:photo-1740635341299-3b8e3490f546", "au": "y3c500c319d"}, {"en": "wearing a uniform", "es": "usar uniforme", "v": "f", "img": "u:photo-1729284440498-19b2295ac7bb", "au": "y384ea788ab"}, {"en": "new classmates", "es": "compañeros nuevos", "v": "m", "img": "u:photo-1594608661623-aa0bd3a69d98", "au": "y34af8f0081"}], "sentences": [{"en": "I'm used to getting up early, so it doesn't bother me.", "es": "Estoy acostumbrado a madrugar, así que no me molesta.", "v": "f", "img": "u:photo-1550534791-2677533605ab", "au": "y36bdfe3577"}, {"en": "It took me a year to get used to the winters in Minneapolis.", "es": "Me tomó un año acostumbrarme a los inviernos de Minneapolis.", "v": "m", "img": "u:photo-1477601263568-180e2c6d046e", "au": "y3fe0c01972"}, {"en": "She isn't used to wearing a uniform at school.", "es": "Ella no está acostumbrada a usar uniforme en el colegio.", "v": "f", "img": "u:photo-1768896067521-827fab4a59e8", "au": "y3f4d299584"}, {"en": "Are you used to your new school yet?", "es": "¿Ya estás acostumbrado a tu nuevo colegio?", "v": "m", "img": "u:photo-1613896527026-f195d5c818ed", "au": "y35421f769f"}, {"en": "You'll get used to it; just give it some time.", "es": "Te vas a acostumbrar; solo dale tiempo.", "v": "f", "img": "u:photo-1581998392741-67879e0ef04a", "au": "y3049586bc6"}, {"en": "After six months, we finally felt at home in Denver.", "es": "Después de seis meses, por fin nos sentimos en casa en Denver.", "v": "m", "img": "u:photo-1758227365187-016878604d94", "au": "y3c0d45da45"}]}, "t10p1": {"tip": "<p><b>too + adjetivo (+ for alguien) + to + verbo</b> = demasiado … para:<br>\n<i>This backpack is <b>too heavy to</b> carry.</i> · <i>The soup is <b>too hot for me to</b> eat.</i></p>\n<p><b>adjetivo + enough + to + verbo</b> = suficientemente … para (¡<b>enough</b> va DESPUÉS del adjetivo!):<br>\n<i>He isn't <b>old enough to</b> stay home alone.</i> · <s>enough old</s> (incorrecto)</p>\n<p><b>enough + sustantivo</b> (¡ANTES del sustantivo!): <i>We don't have <b>enough time</b>.</i></p>\n<p><b>too much</b> + incontable (<i>too much homework</i>) · <b>too many</b> + plural (<i>too many people</i>).</p>\n<p><b>too</b> es negativo (un problema); para algo positivo usa <b>very</b> o <b>so</b>: <i>The park is <b>very</b> nice.</i></p>", "vocab": [{"en": "too tired to play", "es": "demasiado cansado para jugar", "v": "f", "img": "u:photo-1644459436041-06c8c59478e1", "au": "y3f9638cd7d"}, {"en": "old enough to stay home alone", "es": "con edad suficiente para quedarse solo en casa", "v": "m", "img": "u:photo-1780130487332-b6a96a31b024", "au": "y3f9d95c715"}, {"en": "enough time to finish", "es": "suficiente tiempo para terminar", "v": "f", "img": "u:photo-1649252504109-686f70fa38af", "au": "y32389fcc3b"}, {"en": "not tall enough", "es": "no lo suficientemente alto", "v": "m", "img": "u:photo-1684009395244-b5027aa10e0f", "au": "y3e7857671e"}, {"en": "too many people", "es": "demasiada gente", "v": "f", "img": "u:photo-1502136969935-8d8eef54d77b", "au": "y3fe2da692a"}, {"en": "too much homework", "es": "demasiada tarea", "v": "m", "img": "u:photo-1517673132405-a56a62b18caf", "au": "y37eb39854b"}, {"en": "big enough for", "es": "suficientemente grande para", "v": "f", "img": "u:photo-1578645510447-e20b4311e3ce", "au": "y3e0e63d2a6"}, {"en": "too expensive", "es": "demasiado caro", "v": "m", "img": "u:photo-1741389544696-0750a7ac6bbb", "au": "y3bbad25dbd"}], "sentences": [{"en": "My little brother isn't old enough to go to the park alone.", "es": "Mi hermanito no tiene edad suficiente para ir solo al parque.", "v": "f", "img": "u:photo-1749015314315-1c193d1f67e3", "au": "y31ced3a16d"}, {"en": "This backpack is too heavy to carry to school.", "es": "Esta mochila es demasiado pesada para llevarla al colegio.", "v": "m", "img": "u:photo-1581605405669-fcdf81165afa", "au": "y30238040c8"}, {"en": "We don't have enough time to visit both museums.", "es": "No tenemos suficiente tiempo para visitar ambos museos.", "v": "f", "img": "u:photo-1669896857224-cc0068a0b608", "au": "y3410ec4e5a"}, {"en": "The soup was too hot for me to eat.", "es": "La sopa estaba demasiado caliente para que yo la comiera.", "v": "m", "img": "u:photo-1518737003272-dac7c4760d5e", "au": "y37b254395a"}, {"en": "Is your English good enough to understand cartoons?", "es": "¿Tu inglés es lo suficientemente bueno para entender dibujos animados?", "v": "f", "img": "u:photo-1752652010704-11c6a68ce66e", "au": "y399f48a2de"}, {"en": "There were too many people at the concert.", "es": "Había demasiada gente en el concierto.", "v": "m", "img": "u:photo-1574504212584-29a03eb6e41e", "au": "y368838f7af"}]}, "t10p2": {"tip": "<p><b>wish</b> sirve para hablar de cosas que <b>no son reales ahora</b> y nos gustaría cambiar. ¡El verbo “retrocede” un tiempo: presente → pasado!</p>\n<p>1️⃣ <b>wish + pasado simple</b>: <i>I <b>wish</b> I <b>had</b> more time.</i> (No tengo tiempo.) · <i>I wish I <b>lived</b> closer to school.</i> (Vivo lejos.)</p>\n<p>2️⃣ Con <i>be</i> se usa <b>were</b> para todas las personas: <i>I wish I <b>were</b> taller.</i> · <i>I wish it <b>were</b> Friday.</i></p>\n<p>3️⃣ Para habilidades usa <b>could</b>: <i>I <b>wish</b> I <b>could</b> speak Japanese.</i> (No puedo.)</p>\n<p><b>If only …</b> = igual que <i>wish</i>, pero más emocional: <i><b>If only</b> I <b>knew</b> the answer!</i></p>\n<p>Después de <i>wish</i> no uses presente: <s>I wish I have</s> (incorrecto) → <i>I wish I <b>had</b></i> (correcto).</p>", "vocab": [{"en": "I wish I had more time", "es": "ojalá tuviera más tiempo", "v": "f", "img": "u:photo-1550534791-2677533605ab", "au": "y3a52508151"}, {"en": "I wish I were taller", "es": "ojalá fuera más alto", "v": "m", "img": "u:photo-1706841533842-3bbfafb7fdbc", "au": "y34e69032c9"}, {"en": "I wish I could speak Japanese", "es": "ojalá pudiera hablar japonés", "v": "f", "img": "u:photo-1486303954368-398fea0e72cd", "au": "y32ecf281d6"}, {"en": "I wish I lived closer to school", "es": "ojalá viviera más cerca del colegio", "v": "m", "img": "u:photo-1761266158207-26a70892763d", "au": "y3d5a4c98e4"}, {"en": "If only I knew!", "es": "¡Si tan solo supiera!", "v": "f", "img": "u:photo-1546458932-22b70896a584", "au": "y3684ce8daf"}, {"en": "I wish I didn't have homework", "es": "ojalá no tuviera tarea", "v": "m", "img": "u:photo-1677091407437-5c0a10905046", "au": "y3b6b353641"}, {"en": "I wish I had a dog", "es": "ojalá tuviera un perro", "v": "f", "img": "u:photo-1586537333626-238ebc85e19f", "au": "y3f6b06b794"}, {"en": "I wish it were Friday", "es": "ojalá fuera viernes", "v": "m", "img": "u:photo-1633526543814-9718c8922b7a", "au": "y3cbd44f2e5"}], "sentences": [{"en": "I wish I spoke Japanese. My trip to Tokyo would be easier.", "es": "Ojalá hablara japonés. Mi viaje a Tokio sería más fácil.", "v": "f", "img": "u:photo-1560360482-d5588f13d530", "au": "y3ffa8153a3"}, {"en": "I wish I had more time to play video games.", "es": "Ojalá tuviera más tiempo para jugar videojuegos.", "v": "m", "img": "u:photo-1554410637-1a8267402b57", "au": "y3fbce8dbca"}, {"en": "I wish I could cook like my grandmother.", "es": "Ojalá pudiera cocinar como mi abuela.", "v": "f", "img": "u:photo-1761839257845-9283b7d1b933", "au": "y316f7f54c9"}, {"en": "I wish it were summer. I hate the cold!", "es": "Ojalá fuera verano. ¡Odio el frío!", "v": "m", "img": "u:photo-1546193229-e200b04daf4e", "au": "y32a3d0e3df"}, {"en": "She wishes she lived closer to her best friend.", "es": "Ella desearía vivir más cerca de su mejor amiga.", "v": "f", "img": "u:photo-1588696191779-61dde1b83475", "au": "y39dce4eecb"}, {"en": "I wish I weren't so nervous before exams.", "es": "Ojalá no me pusiera tan nervioso antes de los exámenes.", "v": "m", "img": "u:photo-1598981457915-aea220950616", "au": "y366d6c5dae"}]}, "t11p1": {"tip": "<p><b>Contables</b>: se pueden contar (<i>one egg, two eggs</i>) → <b>many</b>, <b>a few</b>, <b>How many …?</b><br>\n<b>Incontables</b>: no tienen plural (<i>milk, rice, money, water</i>) → <b>much</b>, <b>a little</b>, <b>How much …?</b></p>\n<p><b>a lot of / lots of</b> sirven para los dos: <i>a lot of eggs</i>, <i>a lot of milk</i>.<br>\nEn oraciones afirmativas se prefiere <b>a lot of</b>; <b>much</b> suena formal en afirmativo y es normal en negativas y preguntas: <i>We don't have <b>much</b> time.</i></p>\n<p><b>some</b> → afirmativas y <b>ofrecimientos/pedidos</b>: <i>Would you like <b>some</b> juice?</i><br>\n<b>any</b> → negativas y preguntas: <i>Is there <b>any</b> milk?</i> · <i>There isn't <b>any</b> bread.</i></p>\n<p>Para “contar” incontables usa envases: <b>a carton of</b> milk · <b>a loaf of</b> bread · <b>a bottle of</b> water · <b>a bag of</b> flour · <b>a can of</b> beans.</p>", "vocab": [{"en": "How much milk is left?", "es": "¿Cuánta leche queda?", "v": "f", "img": "u:photo-1517448931760-9bf4414148c5", "au": "y32a1e48bd8"}, {"en": "How many eggs do we need?", "es": "¿Cuántos huevos necesitamos?", "v": "m", "img": "u:photo-1498654077810-12c21d4d6dc3", "au": "y35bb036558"}, {"en": "a lot of / lots of", "es": "mucho / muchos", "v": "f", "img": "u:photo-1519087318609-bfb5c04c27f5", "au": "y386c8be269"}, {"en": "some bread", "es": "algo de pan", "v": "m", "img": "u:photo-1559811814-e2c57b5e69df", "au": "y3d335e06e8"}, {"en": "any rice", "es": "algo de / nada de arroz", "v": "f", "img": "u:photo-1536304993881-ff6e9eefa2a6", "au": "y3e02942ecd"}, {"en": "a carton of milk", "es": "un cartón de leche", "v": "m", "img": "u:photo-1553301803-768cd4a59b9c", "au": "y3101de056d"}, {"en": "a loaf of bread", "es": "una barra de pan", "v": "f", "img": "u:photo-1534620808146-d33bb39128b2", "au": "y3953fe9514"}, {"en": "a bottle of water", "es": "una botella de agua", "v": "m", "img": "u:photo-1616118132534-381148898bb4", "au": "y3a0d7721b6"}], "sentences": [{"en": "How much money do we have left for the school trip?", "es": "¿Cuánto dinero nos queda para la excursión del colegio?", "v": "f", "img": "u:photo-1512075135822-67cdd9dd7314", "au": "y3a5b06a04d"}, {"en": "We don't have many eggs, so let's buy a dozen.", "es": "No tenemos muchos huevos, así que compremos una docena.", "v": "m", "img": "u:photo-1648141499246-97a0eb56c2fd", "au": "y33fd90d688"}, {"en": "Is there any milk in the fridge?", "es": "¿Hay leche en la nevera?", "v": "f", "img": "u:photo-1737363625046-290a4c1e648e", "au": "y301fa8b689"}, {"en": "Could you grab a loaf of bread and some cheese?", "es": "¿Puedes traer una barra de pan y algo de queso?", "v": "m", "img": "u:photo-1743193144224-d2db90ea7784", "au": "y304666742a"}, {"en": "We've run out of cereal, so add it to the shopping list.", "es": "Se nos acabó el cereal; agrégalo a la lista de compras.", "v": "f", "img": "u:photo-1741521641159-41f82f656f75", "au": "y3b56b595c9"}, {"en": "There's a lot of homework, so it'll take a while.", "es": "Hay mucha tarea, así que va a demorar un rato.", "v": "m", "img": "u:photo-1637580724561-ee200f66dae3", "au": "y3c70e168e0"}]}, "t11p2": {"tip": "<p>Algunas palabras son <b>contables en español</b> pero <b>incontables en inglés</b>. ¡Nunca llevan <i>a/an</i> ni <i>-s</i>!</p>\n<p><b>advice</b> (consejo) · <b>information</b> · <b>furniture</b> (muebles) · <b>luggage / baggage</b> · <b>equipment</b> · <b>homework</b> · <b>news</b> · <b>research</b> · <b>feedback</b></p>\n<p>Para contarlas: <b>a piece of</b> → <i>a piece of advice</i>, <i>two pieces of furniture</i>, <i>a piece of news</i>.<br>\nIncorrecto: <s>an advice</s>, <s>informations</s>, <s>furnitures</s></p>\n<p><b>news</b> termina en -s pero es <b>singular</b>: <i>The news <b>is</b> good.</i></p>\n<p>Palabras que <b>cambian de significado</b>:<br>\n<i>chicken</i> (el pollo, la carne) / <i>a chicken</i> (una gallina) · <i>paper</i> (papel) / <i>a paper</i> (un periódico o un ensayo)<br>\n<i>glass</i> (vidrio) / <i>a glass</i> (un vaso) · <i>room</i> (espacio) / <i>a room</i> (una habitación)<br>\n<i>experience</i> (experiencia, práctica) / <i>an experience</i> (una vivencia)</p>", "vocab": [{"en": "a piece of advice", "es": "un consejo", "v": "f", "img": "u:photo-1593100126453-19b562a800c1", "au": "y338fc6bb8b"}, {"en": "some information", "es": "(algo de) información", "v": "m", "img": "u:photo-1774261157770-4035a272b017", "au": "y3b04e005cf"}, {"en": "furniture", "es": "muebles", "v": "f", "img": "u:photo-1505693416388-ac5ce068fe85", "au": "y3b15e483d4"}, {"en": "luggage", "es": "equipaje", "v": "m", "img": "u:photo-1772466669620-310c35f9deb2", "au": "y384719c065"}, {"en": "The news is good.", "es": "Las noticias son buenas.", "v": "f", "img": "u:photo-1758687126877-b37052a20a4d", "au": "y368e8e2f2a"}, {"en": "sports equipment", "es": "equipo deportivo", "v": "m", "img": "u:photo-1632755898125-36cd72575dde", "au": "y3787c18410"}, {"en": "a chicken / chicken", "es": "una gallina / el pollo (carne)", "v": "f", "img": "u:photo-1548550023-2bdb3c5beed7", "au": "y3b8a7d2036"}, {"en": "a paper / paper", "es": "un periódico, un ensayo / papel", "v": "m", "img": "u:photo-1566378246598-5b11a0d486cc", "au": "y3b5ab355b7"}], "sentences": [{"en": "Let me give you a piece of advice: always read the instructions.", "es": "Déjame darte un consejo: siempre lee las instrucciones.", "v": "f", "img": "u:photo-1549737221-bef65e2604a6", "au": "y3ca05dcf53"}, {"en": "The news is good: our team won the final!", "es": "Las noticias son buenas: ¡nuestro equipo ganó la final!", "v": "m", "img": "u:photo-1540688030071-628c72ab0b08", "au": "y33faca9c0b"}, {"en": "Can I have two hot chocolates and a muffin, please?", "es": "¿Me da dos chocolates calientes y un muffin, por favor?", "v": "f", "img": "u:photo-1550502385-569f695037c5", "au": "y30e616d73b"}, {"en": "We need some new furniture for my bedroom.", "es": "Necesitamos muebles nuevos para mi habitación.", "v": "m", "img": "u:photo-1763478958804-33a0fe7b5137", "au": "y3d72983ea7"}, {"en": "How much luggage are you taking on the school trip?", "es": "¿Cuánto equipaje vas a llevar a la excursión del colegio?", "v": "f", "img": "u:photo-1650531213149-a7ab752bd004", "au": "y31da7fa964"}, {"en": "She has a lot of experience as a goalkeeper.", "es": "Ella tiene mucha experiencia como portera.", "v": "m", "img": "u:photo-1542852869-ecc293ff89c0", "au": "y30d20bc6a3"}]}, "t12p1": {"tip": "<p>Con <b>a</b> = sentido <b>positivo</b> (es poco, ¡pero alcanza!):<br>\n<b>a few</b> + contable plural → <i>I have <b>a few</b> friends at my new school.</i> (unos cuantos)<br>\n<b>a little</b> + incontable → <i>We have <b>a little</b> time. Let's get ice cream.</i> (un poco)</p>\n<p>Sin <b>a</b> = sentido <b>negativo</b> (casi nada, no alcanza):<br>\n<b>few</b> + contable → <i><b>Few</b> people came.</i> (casi nadie)<br>\n<b>little</b> + incontable → <i>There's <b>little</b> hope.</i> (casi ninguna)</p>\n<p><b>quite a few</b> = bastantes (¡un número grande!) · <b>only a few</b> = solo unos pocos · <b>very few / very little</b> = muy pocos / muy poco.</p>\n<p>En conversación, <i>few</i> y <i>little</i> solos suenan formales; es común decir <b>not many / not much</b>.</p>", "vocab": [{"en": "a few friends", "es": "unos cuantos amigos", "v": "f", "img": "u:photo-1502781252888-9143ba7f074e", "au": "y39e9bc3f9f"}, {"en": "few people", "es": "poca gente (casi nadie)", "v": "m", "img": "u:photo-1729147947344-865151ce9abf", "au": "y368484a92f"}, {"en": "a little money", "es": "un poco de dinero", "v": "f", "img": "u:photo-1607863680198-23d4b2565df0", "au": "y35119de05f"}, {"en": "little time", "es": "poco tiempo (casi nada)", "v": "m", "img": "u:photo-1594995846645-d58328c3ffa4", "au": "y38b97ee89f"}, {"en": "quite a few", "es": "bastantes", "v": "f", "img": "u:photo-1567746455504-cb3213f8f5b8", "au": "y3ae4aabeb4"}, {"en": "very little", "es": "muy poco", "v": "m", "img": "u:photo-1577680716097-9a565ddc2007", "au": "y3fc27c4279"}, {"en": "only a few", "es": "solo unos pocos", "v": "f", "img": "u:photo-1642942002989-b11ba2164626", "au": "y3876ed9dbf"}, {"en": "a little bit", "es": "un poquito", "v": "m", "img": "u:photo-1517427294546-5aa121f68e8a", "au": "y30b967fa50"}], "sentences": [{"en": "I have a few friends at my new school, so I won't feel lonely.", "es": "Tengo unos cuantos amigos en mi nuevo colegio, así que no me sentiré solo.", "v": "f", "img": "u:photo-1569617084133-26942bb441f2", "au": "y38439ab8f7"}, {"en": "Few people know that Alaska is twice as big as Texas.", "es": "Poca gente sabe que Alaska es el doble de grande que Texas.", "v": "m", "img": "u:photo-1686065428339-c88c628c6562", "au": "y30cf8db32d"}, {"en": "There's a little juice left. Do you want some?", "es": "Queda un poco de jugo. ¿Quieres?", "v": "f", "img": "u:photo-1600271886742-f049cd451bba", "au": "y39df2539c1"}, {"en": "We have very little time before the game starts.", "es": "Tenemos muy poco tiempo antes de que empiece el partido.", "v": "m", "img": "u:photo-1622659097509-4d56de14539e", "au": "y370065c513"}, {"en": "Quite a few students ride their bikes to school.", "es": "Bastantes estudiantes van al colegio en bicicleta.", "v": "f", "img": "u:photo-1566728060299-ad216d6fa3c1", "au": "y36ac033189"}, {"en": "He has little patience with people who are always late.", "es": "Él tiene poca paciencia con la gente que siempre llega tarde.", "v": "m", "img": "u:photo-1516789032718-1e135060f1c6", "au": "y308dbc3bf8"}]}, "t12p2": {"tip": "<p><b>fewer</b> + contable plural (<i>fewer cars, fewer people</i>) · <b>less</b> + incontable (<i>less traffic, less money</i>).<br>\nEn conversación muchos nativos dicen <i>less people</i>, pero en exámenes y escritura usa <b>fewer</b>.</p>\n<p><b>plenty of</b> = más que suficiente (contable o incontable): <i>We have <b>plenty of</b> time.</i></p>\n<p><b>hardly any</b> = casi nada / casi ninguno: <i>There's <b>hardly any</b> milk left.</i> · <i><b>Hardly any</b> students complained.</i></p>\n<p>Para encuestas y datos:<br>\n<b>a large number of</b> + contable (<i>a large number of users</i>) · <b>a lot of</b> + contable o incontable (<i>a lot of energy</i>)<br>\n<b>the majority of</b> = la mayoría · <b>not many / not much</b> = pocos / poco.</p>", "vocab": [{"en": "fewer cars", "es": "menos carros", "v": "f", "img": "u:photo-1753219882208-05fbc710117e", "au": "y35561e0444"}, {"en": "less pollution", "es": "menos contaminación", "v": "m", "img": "u:photo-1740924771376-7396a0c0c8ca", "au": "y33082e2a4d"}, {"en": "plenty of options", "es": "muchas opciones (de sobra)", "v": "f", "img": "u:photo-1753997738387-780faae9e7da", "au": "y3ffa752273"}, {"en": "hardly any", "es": "casi nada / casi ninguno", "v": "m", "img": "u:photo-1588856062859-561c223f0cdd", "au": "y3a49e7f8dc"}, {"en": "a lot of energy", "es": "mucha energía", "v": "f", "img": "u:photo-1502086223501-7ea6ecd79368", "au": "y394497810b"}, {"en": "a large number of", "es": "un gran número de", "v": "m", "img": "u:photo-1524069290683-0457abfe42c3", "au": "y3949d14f64"}, {"en": "the majority of", "es": "la mayoría de", "v": "f", "img": "u:photo-1758270704417-26c1244cfaf3", "au": "y3e4ad7b6a2"}, {"en": "not many", "es": "no muchos", "v": "m", "img": "u:photo-1613061527119-56ad37b8a581", "au": "y36345ffbf5"}], "sentences": [{"en": "Fewer kids come to school by car now that we have a bike lane.", "es": "Menos niños llegan al colegio en carro ahora que tenemos ciclovía.", "v": "f", "img": "u:photo-1783428669277-c2e73a324f56", "au": "y3dac998459"}, {"en": "We should use less plastic and more reusable bags.", "es": "Deberíamos usar menos plástico y más bolsas reutilizables.", "v": "m", "img": "u:photo-1645129432582-daa7ad8ae176", "au": "y3deccafdb2"}, {"en": "Don't rush. We have plenty of time before the flight.", "es": "No te apures. Tenemos tiempo de sobra antes del vuelo.", "v": "f", "img": "u:photo-1763618769707-3e318c25325f", "au": "y39ec944f0d"}, {"en": "Hardly any students complained about the new school rules.", "es": "Casi ningún estudiante se quejó de las nuevas reglas del colegio.", "v": "m", "img": "u:photo-1509062522246-3755977927d7", "au": "y3c52937672"}, {"en": "A large number of students answered the survey.", "es": "Un gran número de estudiantes respondió la encuesta.", "v": "f", "img": "u:photo-1665979738279-bd2441290e02", "au": "y3d023764e3"}, {"en": "There's a lot of interest in the new science club.", "es": "Hay mucho interés en el nuevo club de ciencias.", "v": "m", "img": "u:photo-1633828763399-e29f1cd3f4c1", "au": "y3731331c45"}]}, "t13p1": {"tip": "<p>Los conectores de <b>contraste</b> unen dos ideas opuestas. ¡Lo difícil es qué va DESPUÉS de cada uno!</p>\n<p>1️⃣ <b>although / even though / but</b> + <b>oración</b> (sujeto + verbo):<br>\n<i><b>Although</b> the flight was late, we arrived on time.</i> · <i>I love cities, <b>but</b> my brother prefers the country.</i></p>\n<p>2️⃣ <b>despite / in spite of</b> + <b>sustantivo</b> o <b>verbo-ING</b>:<br>\n<i><b>Despite</b> the rain, …</i> · <i><b>In spite of</b> being tired, …</i> · <s>Despite it was raining</s> (incorrecto) → <i><b>Although</b> it was raining</i> (correcto)</p>\n<p>3️⃣ <b>However</b> = empieza una <b>nueva oración</b>, con coma:<br>\n<i>The plan was risky. <b>However,</b> we won.</i></p>\n<p><b>even though</b> es más fuerte que <i>although</i>. <b>but</b> va en medio de la oración, con coma antes.</p>", "vocab": [{"en": "however", "es": "sin embargo", "v": "f", "img": "u:photo-1776870706366-5b850e36bdeb", "au": "y35d046e031"}, {"en": "although", "es": "aunque", "v": "m", "img": "u:photo-1510090658125-0706ab1d38e1", "au": "y3ddbe729a1"}, {"en": "even though", "es": "aun cuando (más fuerte)", "v": "f", "img": "u:photo-1640504409849-da005a55cbd3", "au": "y348937c57a"}, {"en": "despite", "es": "a pesar de", "v": "m", "img": "u:photo-1751829282491-47f5849d3790", "au": "y3b988a7a15"}, {"en": "in spite of", "es": "a pesar de", "v": "f", "img": "u:photo-1520891601894-dedf729f78f8", "au": "y37a2536098"}, {"en": "but", "es": "pero", "v": "m", "img": "u:photo-1563252781-2f76e089e889", "au": "y3cf38eab7d"}, {"en": "in spite of the cold", "es": "a pesar del frío", "v": "f", "img": "u:photo-1631779202803-7f1415c87a9d", "au": "y3fb7d9b8f7"}, {"en": "despite the rain", "es": "a pesar de la lluvia", "v": "m", "img": "u:photo-1580560230671-61e01dfdb285", "au": "y3507a60254"}], "sentences": [{"en": "Although the flight was late, we arrived in time for my cousin's party.", "es": "Aunque el vuelo se retrasó, llegamos a tiempo para la fiesta de mi primo.", "v": "f", "img": "u:photo-1765780199629-50df915ccb18", "au": "y31a8872bad"}, {"en": "Despite the rain, hundreds of kids finished the school race.", "es": "A pesar de la lluvia, cientos de niños terminaron la carrera del colegio.", "v": "m", "img": "u:photo-1589556264800-08ae9e129a8c", "au": "y324c1a45aa"}, {"en": "She joined the team even though she was the youngest player.", "es": "Ella entró al equipo aun cuando era la jugadora más joven.", "v": "f", "img": "u:photo-1629977007371-0ba395424741", "au": "y3846161960"}, {"en": "I love big cities, but my sister prefers the countryside.", "es": "Me encantan las grandes ciudades, pero mi hermana prefiere el campo.", "v": "m", "img": "u:photo-1638057733961-591fa542f718", "au": "y3de5ab90bf"}, {"en": "The plan was risky. However, it was a big success.", "es": "El plan era arriesgado. Sin embargo, fue todo un éxito.", "v": "f", "img": "u:photo-1488521787991-ed7bbaae773c", "au": "y347e947ca6"}, {"en": "In spite of his experience, he didn't win the contest.", "es": "A pesar de su experiencia, no ganó el concurso.", "v": "m", "img": "u:photo-1613271752699-ede48a285196", "au": "y3daea96730"}]}, "t13p2": {"tip": "<p><b>Añadir</b> información: <b>also</b> (antes del verbo) · <b>In addition, / Besides,</b> (al inicio, con coma)<br>\n<i>The school is close to my house. <b>In addition,</b> it has a big pool.</i> · <i>She <b>also</b> speaks Portuguese.</i></p>\n<p><b>Causa y resultado</b>: <b>because</b> (causa) · <b>so / as a result / that's why</b> (resultado)<br>\n<i>I was tired, <b>so</b> I went to bed.</i> · <i>It rained all week. <b>As a result,</b> the concert was canceled.</i><br>\n<b>because of</b> + sustantivo: <i>We were late <b>because of</b> the traffic.</i></p>\n<p><b>Contrastar</b>: <i>Online classes save time. <b>On the other hand,</b> they can feel lonely.</i></p>\n<p><b>For example,</b> = dar un ejemplo · <b>In my opinion,</b> = dar tu opinión · <b>To sum up,</b> = para terminar.</p>", "vocab": [{"en": "because", "es": "porque", "v": "f", "img": "u:photo-1577896851231-70ef18881754", "au": "y320de9528f"}, {"en": "so", "es": "así que", "v": "m", "img": "u:photo-1672928499660-58693df7af84", "au": "y392f49a8a4"}, {"en": "as a result", "es": "como resultado", "v": "f", "img": "u:photo-1724086538386-6faf55b76a31", "au": "y3e53c54917"}, {"en": "because of", "es": "debido a / por", "v": "m", "img": "u:photo-1617540189937-c7375feee6ba", "au": "y3102e86489"}, {"en": "also", "es": "también", "v": "f", "img": "u:photo-1474752651386-dc296d69dc90", "au": "y3c7452dcae"}, {"en": "in addition", "es": "además", "v": "m", "img": "u:photo-1632817837084-bf994c18aaf4", "au": "y38f6e52e5a"}, {"en": "besides", "es": "además", "v": "f", "img": "u:photo-1638202951770-2240942c7d1c", "au": "y365c3fc644"}, {"en": "for example", "es": "por ejemplo", "v": "m", "img": "u:photo-1664382953518-4a664ab8a8c9", "au": "y37f5aa6cf1"}], "sentences": [{"en": "Our team won ten games, so we went to the final.", "es": "Nuestro equipo ganó diez partidos, así que pasamos a la final.", "v": "f", "img": "u:photo-1520399636535-24741e71b160", "au": "y37ac744b57"}, {"en": "The school is close to my house. In addition, it has a big pool.", "es": "El colegio está cerca de mi casa. Además, tiene una piscina grande.", "v": "m", "img": "u:photo-1778137859976-0a59e7d98c4b", "au": "y34482a649f"}, {"en": "It rained all week. As a result, the outdoor concert was canceled.", "es": "Llovió toda la semana. Como resultado, se canceló el concierto al aire libre.", "v": "f", "img": "u:photo-1646898279221-dd01c2ecb208", "au": "y3b4ce9cde5"}, {"en": "Online classes save time. On the other hand, they can feel lonely.", "es": "Las clases en línea ahorran tiempo. Por otro lado, pueden sentirse solitarias.", "v": "m", "img": "u:photo-1597933471507-1ca5765185d8", "au": "y312b02aec3"}, {"en": "We were late because of the traffic.", "es": "Llegamos tarde por el tráfico.", "v": "f", "img": "u:photo-1717039044041-82399017e236", "au": "y3f962af978"}, {"en": "She forgot her homework, so she apologized to her teacher.", "es": "Ella olvidó su tarea, así que le pidió disculpas a su profesora.", "v": "m", "img": "u:photo-1588075592405-d3d4f0846961", "au": "y3b8f8272a4"}]}}, "kids": {"t1p1": {"reading": {"title": "The school picnic", "text": "Tomorrow is the school picnic, and Lucy is very excited. \"I think it will be the best day of the year,\" she tells her brother. At school, her teacher asks, \"Who can bring the juice?\" Lucy answers right away: \"I'll bring it! And I'll bring some cookies too.\" The next morning, Lucy looks out the window. The sky is dark and full of big gray clouds. \"Oh no! It's going to rain,\" she says. Her mom smiles. \"Don't worry. I'll take you to school. I'm sure your teachers will find a plan.\" She's right. The class has the picnic in the gym, and everyone has a great time.", "au": "y3259488855", "img": "u:photo-1559838831-d8fbd8af6469", "q": [{"s": "Lucy offers to bring the juice.", "a": "yes"}, {"s": "The sky is sunny in the morning.", "a": "no"}, {"s": "Lucy's mom takes her to school.", "a": "yes"}, {"s": "The class has the picnic in the park.", "a": "no"}]}, "keyq": [{"q": "Is it going to rain today? Look outside.", "es": "¿Va a llover hoy? Mira afuera.", "a": "No, it isn't. The sky is blue, so it's going to be sunny.", "qau": "y3b6a3e221a", "aau": "y3baad4ef6c"}, {"q": "Will you help your mom at home this weekend?", "es": "¿Ayudarás a tu mamá en casa este fin de semana?", "a": "Yes, I will. I'll probably clean my room.", "qau": "y3c9ebe2774", "aau": "y3ef2c66f65"}, {"q": "Do you think your team will win the next game?", "es": "¿Crees que tu equipo ganará el próximo partido?", "a": "Yes, I do. I think we'll definitely win.", "qau": "y37cbb2d51b", "aau": "y324e0698b7"}]}, "t1p2": {"reading": {"title": "Summer plans", "text": "Summer vacation starts next week, and Sofia has a lot of plans. \"I'm going to learn to swim this summer,\" she tells her friend Leo. Her lessons begin soon: \"I'm starting swimming lessons on Monday at ten.\" Leo is excited too. \"We're visiting my grandparents in the mountains in July,\" he says. \"They're likely to take us fishing.\" Sofia has an idea. \"Shall we have a picnic before you leave?\" \"Great idea! I'll bring sandwiches,\" says Leo. \"And I'll bring lemonade, I promise,\" says Sofia. Just then, the bell rings. Class is about to start.", "au": "y32e7a6efb0", "img": "u:photo-1651614158095-b98b6c1da74b", "q": [{"s": "Sofia is going to learn to swim.", "a": "yes"}, {"s": "Sofia's swimming lessons start on Friday.", "a": "no"}, {"s": "Leo is visiting his grandparents in July.", "a": "yes"}, {"s": "Leo is going to bring lemonade.", "a": "no"}]}, "keyq": [{"q": "Are you going to do anything fun this weekend?", "es": "¿Vas a hacer algo divertido este fin de semana?", "a": "Yes, I am. I'm going to ride my bike in the park.", "qau": "y31515159cc", "aau": "y3ded4e5262"}, {"q": "Are you visiting your grandparents soon?", "es": "¿Vas a visitar a tus abuelos pronto?", "a": "Yes, I am. We're visiting them on Sunday.", "qau": "y3b05b5f805", "aau": "y3734018e0f"}, {"q": "Shall I explain it again?", "es": "¿Quieres que lo explique otra vez?", "a": "Yes, please. I'll listen carefully this time.", "qau": "y3f69091d95", "aau": "y3b27878080"}]}, "t2p1": {"reading": {"title": "A puppy of my own", "text": "For years, Mateo wanted a pet of his own. His sister had her own cat, but the cat never played with him. Last summer, his parents finally gave him a puppy. Its name is Rocky, and it's small and brown. Its ears are very long! The first week was crazy. Rocky chewed Mateo's shoes, and Mateo hurt his finger opening a can of dog food. But Mateo did everything on his own: he fed Rocky and washed its bowl every day. Now Rocky wags its tail every time Mateo comes home from school. \"He's my best friend,\" Mateo says.", "au": "y32453430ef", "img": "u:photo-1447684808650-354ae64db5b8", "q": [{"s": "Mateo's sister has her own cat.", "a": "yes"}, {"s": "Rocky is big and black.", "a": "no"}, {"s": "Mateo hurt his knee.", "a": "no"}, {"s": "Rocky wags its tail when Mateo comes home.", "a": "yes"}]}, "keyq": [{"q": "Do you have your own room?", "es": "¿Tienes tu propio cuarto?", "a": "Yes, I do. I have my own room, and its walls are blue.", "qau": "y375bb6777b", "aau": "y343f1a4d9b"}, {"q": "Can you tie your shoes on your own?", "es": "¿Puedes amarrarte los zapatos solo?", "a": "Yes, I can. I tie my shoes on my own every morning.", "qau": "y3753545752", "aau": "y3046c0be50"}, {"q": "Does your head hurt when you don't sleep well?", "es": "¿Te duele la cabeza cuando no duermes bien?", "a": "Yes, it does. My head hurts and my eyes feel tired.", "qau": "y334dbb790b", "aau": "y32a90db8d8"}]}, "t2p2": {"reading": {"title": "The mystery of the missing cookies", "text": "It was my grandma's birthday, and the whole family was at my aunt's house. My mom's famous chocolate cookies were on a plate in the kitchen. At the end of the lunch, my little brother ran in and shouted, \"The cookies are gone!\" Everyone looked at the dog, but Max's bowl was clean. My cousins' hands were clean too. Then I saw chocolate on the corner of my grandpa's mouth. He smiled and said, \"Sorry! They were the best cookies in the world!\" We all laughed. In the end, my aunt's neighbor saved the day. She brought a cake from the bakery at the end of the street.", "au": "y30e01de5f9", "img": "u:photo-1590080874088-eec64895b423", "q": [{"s": "The family was at my aunt's house.", "a": "yes"}, {"s": "The cookies were my grandma's.", "a": "no"}, {"s": "Max's bowl was clean.", "a": "yes"}, {"s": "The cake came from the bakery next to the school.", "a": "no"}]}, "keyq": [{"q": "Is your best friend's name Sam?", "es": "¿Tu mejor amigo se llama Sam?", "a": "No, it isn't. My best friend's name is Laura.", "qau": "y3d38c7eb59", "aau": "y37bd1fcbb6"}, {"q": "Do you spend the holidays at your grandparents' house?", "es": "¿Pasas las vacaciones en la casa de tus abuelos?", "a": "Yes, I do. We always stay at my grandparents' house.", "qau": "y36f0fcf3fe", "aau": "y3e34d4e8a6"}, {"q": "Is there a park at the end of your street?", "es": "¿Hay un parque al final de tu calle?", "a": "Yes, there is. There's a small park at the end of my street.", "qau": "y331be773de", "aau": "y3c314cc162"}]}, "t3p1": {"reading": {"title": "The lost and found box", "text": "Mrs. Lopez is a teacher at Pine Street School. In her classroom, there is a big lost and found box. \"Kids leave everything here,\" she says. \"Pencils, water bottles, sweaters, and once even a toy turtle!\" Returning things is not always easy. Last week, two boys said the same blue lunchbox was theirs. \"It's mine,\" said Ben. \"No, it's mine,\" said Tom. Mrs. Lopez asked a simple question: \"What's inside yours?\" Ben said, \"A sandwich and an apple.\" Tom said, \"Mine has a dinosaur sticker inside.\" She opened it, and there was the dinosaur. The lunchbox was his.", "au": "y3866a4bbd4", "img": "u:photo-1781747835478-a9c3bab5a670", "q": [{"s": "Mrs. Lopez has a lost and found box.", "a": "yes"}, {"s": "Two girls said the lunchbox was theirs.", "a": "no"}, {"s": "Tom's lunchbox has a dinosaur sticker.", "a": "yes"}, {"s": "The lunchbox was Ben's.", "a": "no"}]}, "keyq": [{"q": "Is this pencil yours?", "es": "¿Este lápiz es tuyo?", "a": "No, it isn't mine. I think it's hers.", "qau": "y3adf07fa53", "aau": "y3c81e1dc5d"}, {"q": "Is your backpack the same as mine?", "es": "¿Tu mochila es igual a la mía?", "a": "No, it isn't. Mine is bigger than yours.", "qau": "y30a27ae94d", "aau": "y3b3f104114"}, {"q": "Is that dog yours?", "es": "¿Ese perro es tuyo?", "a": "No, it isn't ours. It's theirs.", "qau": "y39c5f61774", "aau": "y3a076a2052"}]}, "t3p2": {"reading": {"title": "A friend of mine", "text": "When Diego moved to Miami from Bogotá, his English was good, but he made some small mistakes. On his first day at school, he told his teacher, \"Mrs. Hall, a friend of me wants to join the class.\" She smiled and said, \"We say 'a friend of mine.'\" Diego laughed. A week later, he asked a classmate, \"Is yours this pencil?\" She answered, \"Is this yours? No, it's Kevin's. Mine is the one with the stars.\" Little by little, Diego learned the rule. Nobody says \"the mine.\" Now a cousin of his is coming to Miami, and Diego is going to help him with his English.", "au": "y364b6d9fa8", "img": "u:photo-1577896851231-70ef18881754", "q": [{"s": "Diego moved to Miami from Bogotá.", "a": "yes"}, {"s": "Diego's teacher got angry.", "a": "no"}, {"s": "The pencil with stars is Diego's.", "a": "no"}, {"s": "A cousin of his is coming to Miami.", "a": "yes"}]}, "keyq": [{"q": "Is a friend of yours in your class?", "es": "¿Hay un amigo tuyo en tu clase?", "a": "Yes, there is. A friend of mine sits next to me.", "qau": "y3dffce3882", "aau": "y3d224f0a30"}, {"q": "Is it your turn to feed the dog today?", "es": "¿Te toca darle de comer al perro hoy?", "a": "No, it isn't. Today it's my brother's turn, not mine.", "qau": "y3aceac1676", "aau": "y3bcf7baadc"}, {"q": "Are your shoes dirty? Mine are.", "es": "¿Tus zapatos están sucios? Los míos sí.", "a": "Yes, they are. Mine are dirty too.", "qau": "y3502b65d34", "aau": "y34bc23cce9"}]}, "t4p1": {"reading": {"title": "Leo's adventure list", "text": "Leo is ten, and he has a list called \"My Big Adventures.\" He has already done many things on it. He has ridden a horse, he has gone zip-lining in the forest, and he has seen dolphins in the ocean. \"That was a once-in-a-lifetime experience,\" he says. \"I've never felt so happy!\" Some things are harder. Leo hasn't learned to ice-skate yet, and he has never slept in a tent. But his dad has just bought a new tent! So, camping is next. Has Leo ever been scared? \"Yes, I have, on the zip line!\" he laughs. Have you ever made a list like Leo's?", "au": "y309cc903b3", "img": "u:photo-1693878658414-42bed08fc192", "q": [{"s": "Leo has ridden a horse.", "a": "yes"}, {"s": "Leo has slept in a tent many times.", "a": "no"}, {"s": "Leo's dad has just bought a tent.", "a": "yes"}, {"s": "Leo has already learned to ice-skate.", "a": "no"}]}, "keyq": [{"q": "Have you ever seen a dolphin?", "es": "¿Alguna vez has visto un delfín?", "a": "Yes, I have. I've seen dolphins at the beach twice.", "qau": "y349000c6b9", "aau": "y30f00ba9ea"}, {"q": "Have you finished your homework yet?", "es": "¿Ya terminaste tu tarea?", "a": "No, I haven't. I've just started it.", "qau": "y3b081cab0d", "aau": "y3c53b4b55f"}, {"q": "Have you already had lunch today?", "es": "¿Ya almorzaste hoy?", "a": "Yes, I have. I've already had lunch.", "qau": "y308c3f299a", "aau": "y33d03d4d2a"}]}, "t4p2": {"reading": {"title": "Nina and Star", "text": "Nina is eleven, and she has loved horses since she was five. She started riding lessons in 2022. At first, she was scared. \"I fell off twice in my first week,\" she remembers. Last year, her parents gave her a horse named Star. Nina has had Star for one year now, and they have become best friends. She has ridden Star every Saturday since then. In May, Nina won her first ribbon at a local show. \"I've learned so much,\" she says. \"Star has taught me to be patient.\" This month, she has already practiced six times.", "au": "y3e462f0935", "img": "u:photo-1698653223457-05e00ad9cec2", "q": [{"s": "Nina has loved horses since she was five.", "a": "yes"}, {"s": "She started riding lessons in 2020.", "a": "no"}, {"s": "Nina has had Star for three years.", "a": "no"}, {"s": "She won a ribbon in May.", "a": "yes"}]}, "keyq": [{"q": "Have you studied English for a long time?", "es": "¿Has estudiado inglés por mucho tiempo?", "a": "Yes, I have. I've studied English for three years.", "qau": "y3f87c52ffa", "aau": "y3b9a7a8e29"}, {"q": "Have you had your pet for a long time?", "es": "¿Tienes a tu mascota desde hace mucho tiempo?", "a": "Yes, I have. I've had my cat since I was six.", "qau": "y39f319d756", "aau": "y344ef3050a"}, {"q": "Have you been busy lately?", "es": "¿Has estado ocupado últimamente?", "a": "Yes, I have. I've had a lot of homework lately.", "qau": "y3db46f7f6d", "aau": "y336119a812"}]}, "t5p1": {"reading": {"title": "The longest morning", "text": "Last Friday, Emma had a big spelling contest at school. She had practiced for weeks, and she had set an alarm on her mom's phone. But that night, the power went out, and the phone died. When Emma woke up, it was already eight o'clock. By the time she got to the bus stop, the bus had already left. Her dad took her to school, but on the way she realized she had forgotten her lucky pencil at home. When she arrived, her teacher smiled. The contest hadn't started yet, because the judge was late. Emma used a normal pencil, and she won second place!", "au": "y3fd0ea9a3c", "img": "u:photo-1588660500261-47058e961fa6", "q": [{"s": "Emma had practiced for weeks.", "a": "yes"}, {"s": "The bus had already left when she got to the stop.", "a": "yes"}, {"s": "She had forgotten her backpack at home.", "a": "no"}, {"s": "The contest had already finished when she arrived.", "a": "no"}]}, "keyq": [{"q": "Had you eaten breakfast before you came to class today?", "es": "¿Habías desayunado antes de venir a clase hoy?", "a": "Yes, I had. I had eaten cereal with fruit.", "qau": "y329093bc48", "aau": "y3fe3945312"}, {"q": "Had you ever seen snow before you were eight?", "es": "¿Habías visto nieve alguna vez antes de tener ocho años?", "a": "No, I hadn't. I had never seen snow before last year.", "qau": "y334d40c1f9", "aau": "y3d8eaca6ec"}, {"q": "Had the movie started when you got to the theater last time?", "es": "¿La película ya había empezado cuando llegaste al cine la última vez?", "a": "Yes, it had. It had already started, so we missed the beginning.", "qau": "y30dfeb5896", "aau": "y3c89c4642a"}]}, "t5p2": {"reading": {"title": "The wrong backpack", "text": "It all started on the last day of camp. I was very tired because I had played all day. I grabbed my green backpack from the pile and got on the bus. It was raining, and everyone was singing songs. When I opened the backpack at home, I couldn't believe my eyes. Instead of my clothes, there were three toy dinosaurs, a pink flashlight and a book about space. It turned out that I had taken someone else's backpack! Unfortunately, my favorite teddy bear was in mine. My mom called the camp. A girl named Lily had lost a green backpack too. Eventually, we met at the park and exchanged bags. \"Nice teddy bear,\" Lily said, laughing.", "au": "y3c7c360ed2", "img": "u:photo-1678102101284-d5730a2e1654", "q": [{"s": "I was tired because I had played all day.", "a": "yes"}, {"s": "It was sunny when we got on the bus.", "a": "no"}, {"s": "The backpack had three toy dinosaurs.", "a": "yes"}, {"s": "A boy named Max had my backpack.", "a": "no"}]}, "keyq": [{"q": "Were you sleeping when your alarm rang this morning?", "es": "¿Estabas durmiendo cuando sonó tu alarma esta mañana?", "a": "Yes, I was. I was having a funny dream.", "qau": "y37981073c2", "aau": "y316f4b2880"}, {"q": "Did something funny happen to you on vacation?", "es": "¿Te pasó algo divertido en las vacaciones?", "a": "Yes, it did. It all started when my dog jumped into the pool.", "qau": "y37d7cab2fe", "aau": "y37cece6b64"}, {"q": "Was it raining when you got to school today?", "es": "¿Estaba lloviendo cuando llegaste al colegio hoy?", "a": "No, it wasn't. The sun was shining when I arrived.", "qau": "y32825dd7b4", "aau": "y377f049de1"}]}, "t6p1": {"reading": {"title": "Sofi's busy calendar", "text": "Sofi is ten, and her calendar is always full. She goes to school at 7 a.m. from Monday to Friday. On Tuesday afternoon, she has swimming lessons. On the weekend, she plays in the park with her dog, Max. Her birthday is on May 3rd, and her party is in two weeks! Her teacher, Mrs. Lee, gave the class a reading project. \"Please bring it by Friday,\" she said. Sofi read her book until nine o'clock on Wednesday night. On Thursday morning, the project was ready. \"Well done, Sofi!\" said Mrs. Lee. \"You finished early.\"", "au": "y337df5634b", "img": "u:photo-1553729784-e91953dec042", "q": [{"s": "Sofi has swimming lessons on Tuesday afternoon.", "a": "yes"}, {"s": "Sofi's birthday is in June.", "a": "no"}, {"s": "The project was ready on Thursday morning.", "a": "yes"}, {"s": "Sofi read her book until midnight.", "a": "no"}]}, "keyq": [{"q": "Is your birthday in the summer?", "es": "¿Tu cumpleaños es en el verano?", "a": "No, it isn't. It's on March 12th.", "qau": "y3809a3dd51", "aau": "y326dc70fb9"}, {"q": "Do you go to school at 7 a.m.?", "es": "¿Vas al colegio a las 7 a.m.?", "a": "Yes, I do. Classes start at 7 a.m. sharp.", "qau": "y3aa0e5c2b4", "aau": "y34db846ef1"}, {"q": "Do you have to finish your homework by Friday?", "es": "¿Tienes que terminar tu tarea para el viernes?", "a": "Yes, I do. I usually finish it by Thursday.", "qau": "y3625ef34b9", "aau": "y3bbc0b1a12"}]}, "t6p2": {"reading": {"title": "The science fair", "text": "Last month, Lucas's class had a science fair. Their teacher, Mrs. Green, said, \"Finish your projects within two weeks.\" Lucas built a small volcano. He built it for three days, from four to six every afternoon. While he was painting it, his little sister helped him. On the day of the fair, the school bus was late, but Lucas arrived just in time. The fair started on time, at 9 a.m. During the show, the volcano didn't erupt at first, and Lucas was nervous for a few minutes. But in the end, it erupted, and everyone cheered. At the end of the day, Lucas won second prize!", "au": "y3c1492ad21", "img": "u:photo-1663640397122-d50df280b1db", "q": [{"s": "Lucas built a small volcano.", "a": "yes"}, {"s": "Lucas's big brother helped him paint it.", "a": "no"}, {"s": "The fair started late.", "a": "no"}, {"s": "Lucas won second prize at the end of the day.", "a": "yes"}]}, "keyq": [{"q": "Do you talk to your friends during class?", "es": "¿Hablas con tus amigos durante la clase?", "a": "No, I don't. I talk to them during recess.", "qau": "y3fec9a0559", "aau": "y3a8ea9851b"}, {"q": "Did you play video games for two hours yesterday?", "es": "¿Jugaste videojuegos durante dos horas ayer?", "a": "No, I didn't. I played for thirty minutes.", "qau": "y3b5a5c5670", "aau": "y342e9ab471"}, {"q": "Do you usually get to school on time?", "es": "¿Normalmente llegas puntual al colegio?", "a": "Yes, I do. I'm always on time, sometimes early.", "qau": "y3d7fb08d34", "aau": "y3f25711843"}]}, "t7p1": {"reading": {"title": "A trip to the zoo", "text": "On Saturday, Tom and his family went to the zoo. They got on the bus at the corner near his house. Tom sat by the window. The bus went across a big bridge and through a short tunnel. At the zoo, they walked along a path by the lake. The monkeys were in a big cage opposite the lion house. A parrot was on a branch above Tom's head! At noon, they ate sandwiches on a bench near the gift shop. Then they took a little train through the zoo. At the end of the day, Tom fell asleep in the car on the way home.", "au": "y313e733f62", "img": "u:photo-1550977089-b02bb5eea72e", "q": [{"s": "Tom and his family went to the zoo on Saturday.", "a": "yes"}, {"s": "The monkeys were opposite the lion house.", "a": "yes"}, {"s": "They ate lunch in a restaurant.", "a": "no"}, {"s": "Tom fell asleep on the bus on the way home.", "a": "no"}]}, "keyq": [{"q": "Is your classroom on the first floor?", "es": "¿Tu salón está en el primer piso?", "a": "No, it isn't. It's on the second floor.", "qau": "y3a63516b69", "aau": "y3cab6d6fa0"}, {"q": "Is there a park near your house?", "es": "¿Hay un parque cerca de tu casa?", "a": "Yes, there is. There's a big park opposite my house.", "qau": "y31a8e0c87f", "aau": "y3c3e9540f5"}, {"q": "Do you go to school on the bus?", "es": "¿Vas al colegio en bus?", "a": "No, I don't. I go in my mom's car.", "qau": "y34276b268b", "aau": "y33e94e50f0"}]}, "t7p2": {"reading": {"title": "Finding the party", "text": "Ana is invited to her friend Leo's birthday party. Leo's mom sent directions: \"We live at 45 Oak Street. From your school, go straight for two blocks. Turn left at the pet shop. Then cross the street at the traffic light. Our house is on your right, next to a big tree. It's right across from the playground, between a blue house and a yellow house.\" Ana and her dad followed the directions. At the end of the street, they saw balloons on a door. \"We found it!\" Ana shouted. Leo was waiting in front of the house with his dog.", "au": "y31618829fa", "img": "u:photo-1769556920841-2af0677894a7", "q": [{"s": "Leo lives at 45 Oak Street.", "a": "yes"}, {"s": "You turn right at the pet shop.", "a": "no"}, {"s": "Leo's house is right across from the playground.", "a": "yes"}, {"s": "Ana went to the party with her mom.", "a": "no"}]}, "keyq": [{"q": "Is there a park near your house?", "es": "¿Hay un parque cerca de tu casa?", "a": "Yes, there is. It's at the end of my street.", "qau": "y31a8e0c87f", "aau": "y3b22a3b5d1"}, {"q": "Is your school next to a store?", "es": "¿Tu colegio está al lado de una tienda?", "a": "No, it isn't. It's between a bakery and a park.", "qau": "y35eec29e00", "aau": "y30025153fb"}, {"q": "Can you tell me how to get to your classroom?", "es": "¿Puedes decirme cómo llegar a tu salón?", "a": "Yes, I can. Go straight and turn left. It's on your right.", "qau": "y362e4f75ae", "aau": "y3e255421dd"}]}, "t8p1": {"reading": {"title": "Cat or dog?", "text": "Emma wants a pet, and her parents say she can choose a cat or a dog. She makes a list. A dog is much more fun to play with in the park. But a dog is a lot more expensive, because it eats far more food. A cat is a bit quieter, and it isn't as messy as a dog. Emma's friend has a cat, and it's just as friendly as a dog! Her grandma's dog is twice as big as Emma. \"A big dog isn't as easy to take care of as a cat,\" says her mom. In the end, Emma chooses a small, sweet cat named Luna.", "au": "y3ecb7acbe0", "img": "u:photo-1617909962641-473bd11a1afe", "q": [{"s": "A dog eats far more food than a cat.", "a": "yes"}, {"s": "Emma's friend's cat isn't friendly.", "a": "no"}, {"s": "Grandma's dog is twice as big as Emma.", "a": "yes"}, {"s": "Emma chooses a dog.", "a": "no"}]}, "keyq": [{"q": "Is your brother or sister much taller than you?", "es": "¿Tu hermano o hermana es mucho más alto que tú?", "a": "Yes, he is. He's much taller, but I'm faster.", "qau": "y34b86bba99", "aau": "y38a7079ec3"}, {"q": "Is math as easy as English for you?", "es": "¿Para ti las matemáticas son igual de fáciles que el inglés?", "a": "No, it isn't. Math isn't as easy as English for me.", "qau": "y3104e24503", "aau": "y39f63c3b53"}, {"q": "Is your bike slightly bigger than your friend's?", "es": "¿Tu bicicleta es un poco más grande que la de tu amigo?", "a": "Yes, it is. It's slightly bigger and a bit faster.", "qau": "y3c333cd981", "aau": "y3faa2679b9"}]}, "t8p2": {"reading": {"title": "The best week at camp", "text": "Last summer, Nico went to camp for the first time. It was the best week he's ever had. Every day, the activities got better and better. On Monday, they went swimming in the lake. The water was the coldest he's ever felt! On Wednesday, they climbed a hill. The higher they climbed, the more beautiful the view became. On Friday night, they had a campfire. Nico's friend told the funniest story he's ever heard. The more they laughed, the louder they got. Of course, the food was the worst he's ever eaten. \"The sooner I go back, the better!\" Nico says.", "au": "y3c5ef850cf", "img": "u:photo-1478131143081-80f7f84ca84d", "q": [{"s": "The activities got better and better every day.", "a": "yes"}, {"s": "The water in the lake was warm.", "a": "no"}, {"s": "The food was the best Nico has ever eaten.", "a": "no"}, {"s": "They had a campfire on Friday night.", "a": "yes"}]}, "keyq": [{"q": "Is pizza the best food you've ever had?", "es": "¿La pizza es la mejor comida que has probado?", "a": "Yes, it is. It's by far the best food I've ever had.", "qau": "y3d02946dc9", "aau": "y3af5043757"}, {"q": "Is soccer one of the most popular sports at your school?", "es": "¿El fútbol es uno de los deportes más populares en tu colegio?", "a": "Yes, it is. It's by far the most popular sport there.", "qau": "y3ad41be3bc", "aau": "y39e4a0f9ce"}, {"q": "Do you agree that the more you read, the more you learn?", "es": "¿Estás de acuerdo en que cuanto más lees, más aprendes?", "a": "Yes, I do. The more I read, the more words I learn.", "qau": "y3d51adc99f", "aau": "y39f2294e9d"}]}, "t9p1": {"reading": {"title": "When Grandpa was little", "text": "My grandpa Luis loves telling me about his childhood. He used to live on a small farm. He didn't use to have video games or a tablet. After school, he would feed the chickens and play soccer with his brothers. He used to have a dog named Toby. On rainy days, they would play board games for hours. There was no TV in his house, so he would listen to stories on the radio. \"Did you use to get bored?\" I asked. \"Never!\" he said. Now Grandpa lives in the city with us. He doesn't feed chickens anymore, but he still plays board games with me.", "au": "y3789759199", "img": "u:photo-1758612898846-12ca8027eb7c", "q": [{"s": "Grandpa used to live on a small farm.", "a": "yes"}, {"s": "Grandpa used to play video games.", "a": "no"}, {"s": "Grandpa used to have a dog named Toby.", "a": "yes"}, {"s": "Grandpa still feeds chickens.", "a": "no"}]}, "keyq": [{"q": "Did you use to watch cartoons when you were little?", "es": "¿Veías dibujos animados cuando eras pequeño?", "a": "Yes, I did. I used to watch them every morning.", "qau": "y30b808201a", "aau": "y3c2764ea1b"}, {"q": "Did you use to have a favorite toy?", "es": "¿Tenías un juguete favorito?", "a": "Yes, I did. I used to have a big teddy bear.", "qau": "y396009360c", "aau": "y35416e301a"}, {"q": "Did you use to like vegetables?", "es": "¿Antes te gustaban las verduras?", "a": "No, I didn't. I didn't use to like them, but now I do.", "qau": "y3fa2c54dc6", "aau": "y335664f54b"}]}, "t9p2": {"reading": {"title": "A new school in Texas", "text": "Last year, Valentina moved from Bogotá to Houston with her family. At first, everything was new. She wasn't used to the hot weather. She also wasn't used to speaking English all day at school. \"I had to get used to eating lunch at eleven,\" she says. Her new classmates were friendly, and her teacher, Mrs. Brown, helped her a lot. She also had to get used to riding a big yellow school bus. Now, after six months, she's used to her new school. She even plays soccer at recess with her new friends. \"I'm still not used to the spicy food,\" she laughs, \"but I'll get used to it.\"", "au": "y3de7b64e5c", "img": "u:photo-1573086490982-98a5ce8fa45d", "q": [{"s": "Valentina moved to Houston with her family.", "a": "yes"}, {"s": "Valentina was used to the hot weather.", "a": "no"}, {"s": "Valentina had to get used to riding a school bus.", "a": "yes"}, {"s": "Valentina is used to the spicy food now.", "a": "no"}]}, "keyq": [{"q": "Are you used to getting up early?", "es": "¿Estás acostumbrado a madrugar?", "a": "Yes, I am. I'm used to getting up at six for school.", "qau": "y37b00de11f", "aau": "y39a53155c7"}, {"q": "Are you used to doing homework every day?", "es": "¿Estás acostumbrado a hacer tareas todos los días?", "a": "Yes, I am. I'm used to doing it after lunch.", "qau": "y3266849a41", "aau": "y3f0a34fd85"}, {"q": "Is it easy for you to get used to new things?", "es": "¿Te resulta fácil acostumbrarte a cosas nuevas?", "a": "Yes, it is. I get used to new things very fast.", "qau": "y34f4317c15", "aau": "y36edf1e797"}]}, "t10p1": {"reading": {"title": "The big day at the water park", "text": "Sofia was very excited about her birthday trip to the water park. But some things went wrong. First, her backpack was too heavy to carry, so her dad took it. Then her little brother Tomás wasn't tall enough to go on the biggest slide. He was very sad! Sofia was tall enough, but the line was too long. There were too many people and not enough time to try every slide. In the afternoon, it was too hot to stay in the sun, so they ate ice cream under a tree. Still, Sofia loved her day. \"Next year Tomás will be tall enough, and we'll come early!\"", "au": "y3eb209bebe", "img": "u:photo-1596522353318-82979c65cc4a", "q": [{"s": "Sofia's backpack was too heavy to carry.", "a": "yes"}, {"s": "Tomás was tall enough to go on the biggest slide.", "a": "no"}, {"s": "There was enough time to try every slide.", "a": "no"}, {"s": "They ate ice cream under a tree.", "a": "yes"}]}, "keyq": [{"q": "Are you old enough to stay home alone?", "es": "¿Tienes edad suficiente para quedarte solo en casa?", "a": "No, I'm not. I'm too young to stay home alone.", "qau": "y3c5b4310f5", "aau": "y3a1cce17c4"}, {"q": "Is your bedroom big enough for a sleepover?", "es": "¿Tu habitación es lo suficientemente grande para una pijamada?", "a": "No, it isn't. It's too small for five friends.", "qau": "y32cbf4110a", "aau": "y370ecde395"}, {"q": "Do you have enough time to play after school?", "es": "¿Tienes suficiente tiempo para jugar después del colegio?", "a": "Yes, I do. I have enough time to play for an hour.", "qau": "y399ca99820", "aau": "y314761148d"}]}, "t10p2": {"reading": {"title": "Dear Ms. Grace", "text": "Dear Ms. Grace, I'm ten years old and I live in a small apartment. I really love animals, and I wish I had a dog. My parents say our apartment is too small. I also wish I lived in a house with a big garden. If only my parents could see how much I want a pet! Sad in the City\n\nDear Sad, I understand you! Many kids wish they had a pet. A dog needs a lot of space, but a fish or a hamster doesn't. Talk to your parents about a small pet. You can also visit animals at a shelter on weekends. Don't just wish for a pet. Show your parents you are ready! Ms. Grace", "au": "y3cc9315efa", "img": "u:photo-1699434300927-d982927b4892", "q": [{"s": "The child wishes he or she had a dog.", "a": "yes"}, {"s": "The child lives in a big house with a garden.", "a": "no"}, {"s": "Ms. Grace says a fish needs a lot of space.", "a": "no"}, {"s": "Ms. Grace says the child can visit animals at a shelter.", "a": "yes"}]}, "keyq": [{"q": "Do you wish you had a pet?", "es": "¿Te gustaría tener una mascota?", "a": "Yes, I do. I wish I had a cat.", "qau": "y3c197cea25", "aau": "y37001bc42e"}, {"q": "Do you wish you could fly?", "es": "¿Te gustaría poder volar?", "a": "Yes, I do. I wish I could fly to school!", "qau": "y3d8cdf3ceb", "aau": "y3a968b37cd"}, {"q": "Do you wish it were summer now?", "es": "¿Te gustaría que fuera verano ahora?", "a": "No, I don't. I wish it were my birthday!", "qau": "y3c3ac5e829", "aau": "y3bd728c28e"}]}, "t11p1": {"reading": {"title": "Pancakes for Mom", "text": "On Saturday, Lucas and his sister Emma wanted to make pancakes for their mom's birthday. First, they checked the kitchen. There wasn't much milk, only half a carton. \"How many eggs do we have?\" Emma asked. \"Not many. Only two,\" Lucas answered. They needed some flour too, but there wasn't any. So Dad took them to the store. They bought a bag of flour, a carton of milk, six eggs and a bottle of syrup. Lucas wanted a lot of candy, but Dad said no. At home, they made lots of pancakes. \"How many did you make?\" Mom asked. \"A lot!\" they laughed.", "au": "y38fe7b4f9d", "img": "u:photo-1605433246995-23f532d1e001", "q": [{"s": "There was a lot of milk in the kitchen.", "a": "no"}, {"s": "They had only two eggs.", "a": "yes"}, {"s": "There was some flour in the kitchen.", "a": "no"}, {"s": "They bought a bag of flour.", "a": "yes"}]}, "keyq": [{"q": "Do you drink a lot of water every day?", "es": "¿Tomas mucha agua todos los días?", "a": "Yes, I do. I drink a lot of water at school.", "qau": "y3ff25eb5a8", "aau": "y31e58a6889"}, {"q": "Are there many kids in your class?", "es": "¿Hay muchos niños en tu clase?", "a": "Yes, there are. There are twenty-five kids in my class.", "qau": "y3e224ae57b", "aau": "y32c9d254c7"}, {"q": "Is there any ice cream in your fridge?", "es": "¿Hay helado en tu nevera?", "a": "No, there isn't. There isn't any ice cream today.", "qau": "y341119e39f", "aau": "y3c540f786b"}]}, "t11p2": {"reading": {"title": "Camping with Grandpa", "text": "Last summer, Mia went camping with her grandpa for the first time. Before the trip, she asked her mom for advice. Her mom gave her a great piece of advice: \"Don't take a lot of luggage. Just bring one backpack.\" Grandpa had all the equipment: a tent, two sleeping bags and a small stove. At the campsite, there was a lot of room to play. A ranger gave them some information about the animals in the forest. At night, they cooked chicken and looked at the stars. Camping was a wonderful experience for Mia. On the last day, Grandpa read the paper and said, \"The news is good. Sunny weather all week!\"", "au": "y360256c5b7", "img": "u:photo-1674230316788-d9c8b92f0d63", "q": [{"s": "Mia's mom gave her a piece of advice.", "a": "yes"}, {"s": "Mia took three suitcases.", "a": "no"}, {"s": "A ranger gave them information about the animals.", "a": "yes"}, {"s": "The news was bad: rain all week.", "a": "no"}]}, "keyq": [{"q": "Can you give me a piece of advice about school?", "es": "¿Me puedes dar un consejo sobre el colegio?", "a": "Yes, I can. Always do your homework early.", "qau": "y391a7e3a77", "aau": "y36aa01237b"}, {"q": "Do you have much homework today?", "es": "¿Tienes mucha tarea hoy?", "a": "No, I don't. I don't have much homework today.", "qau": "y3c4dfc2072", "aau": "y3fbb3011c9"}, {"q": "Is there much room in your bedroom?", "es": "¿Hay mucho espacio en tu habitación?", "a": "Yes, there is. There's a lot of room for my toys.", "qau": "y3a9aca2178", "aau": "y31b33fe189"}]}, "t12p1": {"reading": {"title": "Two brothers, two attitudes", "text": "Sam and Max are brothers, but they see the world very differently. Last Saturday it rained, and they couldn't play soccer in the park. Sam said, \"We have a few board games and a little time before lunch. Let's play!\" Max didn't agree. \"There's very little to do inside, and few of my friends are online.\" Sam just smiled. He invited a few neighbors, and quite a few kids came to play. Max stayed in his room for a little while. Then he heard laughing and joined the game. He had a lot of fun. Now, when Max feels sad, Sam says, \"Remember, a little fun is better than none!\"", "au": "y39091356de", "img": "u:photo-1629760946220-5693ee4c46ac", "q": [{"s": "It rained last Saturday.", "a": "yes"}, {"s": "Sam thought there was very little to do inside.", "a": "no"}, {"s": "Quite a few kids came to play.", "a": "yes"}, {"s": "Max stayed in his room all day.", "a": "no"}]}, "keyq": [{"q": "Do you have a few minutes to play?", "es": "¿Tienes unos minutos para jugar?", "a": "Yes, I do. I have a few minutes before dinner.", "qau": "y3c47719afc", "aau": "y3196c7fa81"}, {"q": "Do you have a little time to read every day?", "es": "¿Tienes un poco de tiempo para leer todos los días?", "a": "Yes, I do. I read a little before bed.", "qau": "y3bed145359", "aau": "y31534535a1"}, {"q": "Do many kids in your class have a pet?", "es": "¿Muchos niños de tu clase tienen mascota?", "a": "No, they don't. Only a few kids have a pet.", "qau": "y3600f18c07", "aau": "y33e5011510"}]}, "t12p2": {"reading": {"title": "Our class survey", "text": "Ms. Lopez's class did a survey about how kids get to school. They asked two hundred students. The majority of them walk or ride a bike. Fewer parents drive their kids to school than last year. There is less traffic and less noise in the morning. A large number of kids said they have more energy in class. Hardly any students take the bus now. Only a few kids don't like walking in the rain. Many students said they have plenty of time to talk with friends on the way. \"Walking is fun,\" says the class poster. \"And it's good for the planet!\"", "au": "y3fcfa8a773", "img": "u:photo-1761266158207-26a70892763d", "q": [{"s": "The class asked two hundred students.", "a": "yes"}, {"s": "The majority of students go to school by car.", "a": "no"}, {"s": "There is less traffic in the morning.", "a": "yes"}, {"s": "A large number of students take the bus.", "a": "no"}]}, "keyq": [{"q": "Do you eat less candy than before?", "es": "¿Comes menos dulces que antes?", "a": "Yes, I do. I eat less candy now.", "qau": "y3681ccc109", "aau": "y3eae230c4a"}, {"q": "Are there fewer kids in your class this year?", "es": "¿Hay menos niños en tu clase este año?", "a": "No, there aren't. There are plenty of kids in my class.", "qau": "y3ab432a78e", "aau": "y39299749a4"}, {"q": "Do you have plenty of toys at home?", "es": "¿Tienes muchos juguetes en casa?", "a": "Yes, I do. I have plenty of toys and books.", "qau": "y3eba3da8c7", "aau": "y3ab38b7c14"}]}, "t13p1": {"reading": {"title": "The big race", "text": "Lucía is ten years old. Last year she signed up for the school race, although she wasn't a fast runner. Her friends were surprised. Despite her busy week, she practiced in the park three times a week. Her brother helped her, but he preferred to play video games! In March she hurt her foot. In spite of the pain, Lucía didn't give up. She rested and then kept practicing. However, the hardest moment came on race day. It was raining and very cold. Even though she was tired, she kept running. Then she saw her parents with a sign: \"Go, Lucía!\" She didn't win, but she finished despite everything.", "au": "y32ee9c0145", "img": "u:photo-1764186368813-1e7d51ba70d4", "q": [{"s": "Lucía was a fast runner.", "a": "no"}, {"s": "She practiced three times a week.", "a": "yes"}, {"s": "She stopped practicing after she hurt her foot.", "a": "no"}, {"s": "It was raining on race day.", "a": "yes"}]}, "keyq": [{"q": "Do you play outside even though it's cold?", "es": "¿Juegas afuera aun cuando hace frío?", "a": "Yes, I do. I play outside even though it's cold.", "qau": "y347a5ccb97", "aau": "y3ccc2931fe"}, {"q": "Do you do your homework despite being tired?", "es": "¿Haces tu tarea a pesar de estar cansado?", "a": "Yes, I do. I do it despite being tired.", "qau": "y3a973ed930", "aau": "y32ef1fde70"}, {"q": "Is your best friend different from you?", "es": "¿Tu mejor amigo es diferente a ti?", "a": "Yes, she is. I love math, but she prefers art.", "qau": "y3c6c9f3b08", "aau": "y3e679013a3"}]}, "t13p2": {"reading": {"title": "Should our school have a garden?", "text": "Mr. Rivera asked his class a question: should the school have a vegetable garden? The students made a list. First, they wrote the advantages. Gardening is fun, and kids spend more time outside. As a result, they feel happier. In addition, the school could grow fresh vegetables for lunch. Besides, students could learn about plants and insects. On the other hand, the class found some problems. For example, someone has to water the plants every day, even on vacation. Also, some kids are afraid of bees. That's why the class suggested a small garden with easy plants. To sum up, the students said a garden is a great idea.", "au": "y3c4512e4e1", "img": "u:photo-1775568109786-18598bf7b294", "q": [{"s": "Mr. Rivera asked about a vegetable garden.", "a": "yes"}, {"s": "The class found only advantages.", "a": "no"}, {"s": "Some kids are afraid of bees.", "a": "yes"}, {"s": "The class suggested a very big garden.", "a": "no"}]}, "keyq": [{"q": "Do you like weekends because you can play more?", "es": "¿Te gustan los fines de semana porque puedes jugar más?", "a": "Yes, I do. I don't have school, so I can play all day.", "qau": "y3b33c30616", "aau": "y3be619f25f"}, {"q": "Do you feel tired if you don't sleep enough?", "es": "¿Te sientes cansado si no duermes lo suficiente?", "a": "Yes, I do. As a result, I can't pay attention in class.", "qau": "y3407fcdd9a", "aau": "y31a3ecc5a1"}, {"q": "Is it fun to have a pet?", "es": "¿Es divertido tener una mascota?", "a": "Yes, it is. In addition, pets teach you to be responsible.", "qau": "y3cc97b8bea", "aau": "y35bfbf4911"}]}}, "teens": {"t1p1": {"reading": {"title": "Predictions for the future", "text": "Daniel is fifteen, and he makes short videos for his school's channel. This week the topic is the future. \"I think phones will be even more important in ten years,\" he says. \"But I don't think robots will replace teachers.\" Some changes are easy to see. \"Look at our classroom. Everyone has a tablet. Paper notebooks are going to disappear soon.\" After the video, his friend Sara sends him a message. She's nervous about her math exam. Daniel answers right away: \"Don't worry, I'll help you. I'll call you tonight, and you'll probably get a great grade.\"", "au": "y35e93a947a", "img": "u:photo-1526915303387-35900bc4ff33", "q": [{"s": "Daniel thinks robots will replace teachers.", "a": "no"}, {"s": "Everyone in his classroom has a tablet.", "a": "yes"}, {"s": "Sara is nervous about her science exam.", "a": "no"}, {"s": "Daniel offers to call Sara tonight.", "a": "yes"}]}, "keyq": [{"q": "Do you think English will be important for your future?", "es": "¿Crees que el inglés será importante para tu futuro?", "a": "Yes, I do. I think it will help me travel and study abroad.", "qau": "y370cdd22f9", "aau": "y3b7cb28ec2"}, {"q": "Will you probably go out with your friends this weekend?", "es": "¿Probablemente saldrás con tus amigos este fin de semana?", "a": "Yes, I will. We'll probably go to the movies.", "qau": "y3d45a86617", "aau": "y3f85f262c5"}, {"q": "Do you think social media will change a lot in ten years?", "es": "¿Crees que las redes sociales cambiarán mucho en diez años?", "a": "Yes, I do. I think it will be very different.", "qau": "y3a7a95868d", "aau": "y343cfd7e9c"}]}, "t1p2": {"reading": {"title": "Resolutions that actually last", "text": "Every January, lots of teens say, \"This year I'm going to get better grades,\" or \"I'm going to spend less time on my phone.\" By February, many of them forget. Ms. Carter is a school counselor in Seattle, and she has a simple tip: make a real plan. \"An intention is not a plan,\" she explains. \"If you're going to study more, choose a time. Say, 'I'm studying with Mia on Tuesday at four.'\" She also recommends promises to friends. \"When you tell a friend, 'I'll send you my progress every Sunday,' it's easier to keep going.\" This year, her students are going to try it. Their first study group is on Monday.", "au": "y3715401707", "img": "u:photo-1553448539-f6063db586a4", "q": [{"s": "Ms. Carter says an intention is a plan.", "a": "no"}, {"s": "She suggests choosing a time to study.", "a": "yes"}, {"s": "In her example, you send your progress every Friday.", "a": "no"}, {"s": "The students' first study group is on Monday.", "a": "yes"}]}, "keyq": [{"q": "Are you going to do anything after this class?", "es": "¿Vas a hacer algo después de esta clase?", "a": "Yes, I am. I'm going to finish my homework and play video games.", "qau": "y3aa001b0b2", "aau": "y371fadfd45"}, {"q": "Are you doing anything special this weekend?", "es": "¿Vas a hacer algo especial este fin de semana?", "a": "Yes, I am. I'm hanging out with some friends on Saturday.", "qau": "y3e21148ed7", "aau": "y35fc8f380c"}, {"q": "Are you going to learn something new this year?", "es": "¿Vas a aprender algo nuevo este año?", "a": "Yes, I am. I'm going to learn to play the drums.", "qau": "y3ad7f83e79", "aau": "y36fec52897"}]}, "t2p1": {"reading": {"title": "A room of my own", "text": "For years, Valeria shared a bedroom with her little sister. The room was tiny, and its only window faced a wall. \"I love my sister,\" she says, \"but I needed a space of my own.\" Last spring, her family moved to a bigger house, and now Valeria has her own room. It's not big, but its window has a view of the park. The first weekend was crazy. Valeria painted the walls on her own, hurt her back carrying her desk, and cut her finger opening a box. Then her dad came in with his tools and helped her with the shelves. Now she studies, plays her guitar and decorates the room her way.", "au": "y37848c4c98", "img": "u:photo-1597023858048-16e0883ef28a", "q": [{"s": "Valeria shared a room with her brother.", "a": "no"}, {"s": "Her new window has a view of the park.", "a": "yes"}, {"s": "She painted the walls on her own.", "a": "yes"}, {"s": "Her mom helped her with the shelves.", "a": "no"}]}, "keyq": [{"q": "Do you have your own phone?", "es": "¿Tienes tu propio teléfono?", "a": "Yes, I do. I got my own phone when I was twelve.", "qau": "y3c0a870a4c", "aau": "y3e55ca3ed6"}, {"q": "Did you learn to cook on your own?", "es": "¿Aprendiste a cocinar por tu cuenta?", "a": "No, I didn't. My grandma taught me, but now I cook on my own.", "qau": "y34ca1e66ba", "aau": "y3b2147de24"}, {"q": "Does your back hurt after a long day at school?", "es": "¿Te duele la espalda después de un día largo en el colegio?", "a": "Yes, it does. My backpack is really heavy, and it hurts my shoulders.", "qau": "y3bcd019ab9", "aau": "y36c483d9e8"}]}, "t2p2": {"reading": {"title": "Whose hoodie is this?", "text": "Last Saturday, my friends and I had a sleepover at my cousin's house. The next morning, there was a mess at the end of the hallway: jackets, shoes and phone chargers everywhere. \"Whose hoodie is this?\" my cousin asked. It was Sam's. The girls' shoes were all mixed up, and nobody could find Emma's left sneaker. Then we heard a noise. My cousin's puppy was under the bed with the sneaker in its mouth! At the top of the stairs, my aunt was laughing. \"That's Coco's favorite game,\" she said. Then we all had my aunt's famous pancakes for breakfast.", "au": "y3889aea08e", "img": "u:photo-1645301853941-ac972c73ebe9", "q": [{"s": "The sleepover was at my cousin's house.", "a": "yes"}, {"s": "The hoodie was Emma's.", "a": "no"}, {"s": "The puppy had the sneaker.", "a": "yes"}, {"s": "My uncle was at the top of the stairs.", "a": "no"}]}, "keyq": [{"q": "Is your best friend's birthday this month?", "es": "¿El cumpleaños de tu mejor amigo es este mes?", "a": "No, it isn't. My best friend's birthday is in May.", "qau": "y386615ad6b", "aau": "y365e089aaa"}, {"q": "Do you remember the end of your favorite series?", "es": "¿Recuerdas el final de tu serie favorita?", "a": "Yes, I do. The end of the last season was amazing.", "qau": "y35faf49b1b", "aau": "y3a88b3ef82"}, {"q": "Did you sleep at a friend's house last weekend?", "es": "¿Dormiste en casa de un amigo el fin de semana pasado?", "a": "Yes, I did. I slept at Leo's after his birthday party.", "qau": "y3be24ad29f", "aau": "y3e2e4c0544"}]}, "t3p1": {"reading": {"title": "Twin phones", "text": "Our class went on a field trip to the science museum last Friday. On the bus home, Ms. Reyes found a phone under a seat. \"Whose is it?\" she asked. Lucas and Nina both said, \"It's mine!\" The two phones looked exactly the same: black, with a clear case. Ms. Reyes asked, \"What photo does yours have?\" Lucas said, \"Mine has a photo of my dog.\" Nina said, \"Mine has a photo of a beach.\" Ms. Reyes turned it on, and there was the beach. The phone was hers. Two minutes later, Lucas found his in his backpack. \"Sorry,\" he said. \"Yours and mine are twins!\"", "au": "y3c534cd840", "img": "u:photo-1573086490982-98a5ce8fa45d", "q": [{"s": "The phone was under a seat.", "a": "yes"}, {"s": "Lucas's phone has a photo of a beach.", "a": "no"}, {"s": "The phone was Nina's.", "a": "yes"}, {"s": "Lucas never found his phone.", "a": "no"}]}, "keyq": [{"q": "Is this charger yours?", "es": "¿Este cargador es tuyo?", "a": "No, it isn't mine. I think it's his.", "qau": "y33b167fa79", "aau": "y3304d5bbba"}, {"q": "Is your phone newer than mine?", "es": "¿Tu teléfono es más nuevo que el mío?", "a": "Yes, it is. Mine is newer than yours.", "qau": "y303f2bc935", "aau": "y3e7331e226"}, {"q": "Was the idea for the project yours?", "es": "¿La idea del proyecto fue tuya?", "a": "No, it wasn't mine. It was theirs, not ours.", "qau": "y369bea2d8b", "aau": "y3ae67de75a"}]}, "t3p2": {"reading": {"title": "Whose turn is it?", "text": "My friends and I have a band, and we practice every Saturday in Tom's garage. Last week, a cousin of his joined us. He plays the drums, and he's amazing. Before we started, Mia said, \"My guitar has a broken string.\" \"Mine too!\" said Leo. Luckily, Tom had extra strings. Then the big question came: \"Whose turn is it to bring snacks?\" Everyone looked at me. \"It's not mine,\" I said. \"I brought pizza last week.\" Tom's cousin laughed. \"Who's hungry? I brought cookies.\" Now he's a friend of ours, and the best drummer we know.", "au": "y3f2218f356", "img": "u:photo-1777906083633-eb21f20a1c7e", "q": [{"s": "The band practices in Tom's garage.", "a": "yes"}, {"s": "Tom's cousin plays the guitar.", "a": "no"}, {"s": "Leo's guitar also had a broken string.", "a": "yes"}, {"s": "It was my turn to bring snacks.", "a": "no"}]}, "keyq": [{"q": "Is a friend of yours good at music?", "es": "¿Un amigo tuyo es bueno para la música?", "a": "Yes, he is. A friend of mine plays the piano really well.", "qau": "y389ece9992", "aau": "y39a4f52dac"}, {"q": "Is it your turn to choose the movie tonight?", "es": "¿Te toca escoger la película esta noche?", "a": "No, it isn't. It's my sister's turn, not mine.", "qau": "y3930683844", "aau": "y333fde70b7"}, {"q": "Is your phone battery terrible? Mine is.", "es": "¿La batería de tu teléfono es terrible? La mía sí.", "a": "Yes, it is. Mine dies every afternoon.", "qau": "y34cc6e8e7e", "aau": "y346ba5bc85"}]}, "t4p1": {"reading": {"title": "Fifteen before sixteen", "text": "When Maya turned fifteen, she wrote a list called \"Fifteen Before Sixteen.\" It had fifteen things she wanted to do before her next birthday. Ten months later, she has already done eleven of them. She has run a 5K race, she has learned to play the ukulele, and she has gone zip-lining in Costa Rica with her school. \"That was a once-in-a-lifetime experience,\" she says. \"I've never felt so free.\" Some things have been harder. She hasn't learned to surf yet, and she has never performed on stage. \"But I've just signed up for the school talent show!\" Lots of her classmates follow her list online. Have you ever written your own list?", "au": "y3e83e7410d", "img": "u:photo-1712782516688-cbcbf93b1b7c", "q": [{"s": "Maya has already done eleven things on her list.", "a": "yes"}, {"s": "She has learned to surf.", "a": "no"}, {"s": "She has gone zip-lining in Mexico.", "a": "no"}, {"s": "She has just signed up for the talent show.", "a": "yes"}]}, "keyq": [{"q": "Have you ever been to the United States?", "es": "¿Alguna vez has ido a Estados Unidos?", "a": "Yes, I have. I've been to Miami twice.", "qau": "y3821023454", "aau": "y3eb3e1d2aa"}, {"q": "Have you ever performed on stage?", "es": "¿Alguna vez te has presentado en un escenario?", "a": "No, I haven't. I've never done it, but I want to.", "qau": "y397e579953", "aau": "y3e68529fca"}, {"q": "Have you finished your science project yet?", "es": "¿Ya terminaste tu proyecto de ciencias?", "a": "Yes, I have. I've already sent it to my teacher.", "qau": "y3482feaee4", "aau": "y3aed6af28a"}]}, "t4p2": {"reading": {"title": "From the bench to team captain", "text": "Andrés has been the captain of his school's basketball team since September. But his story started much earlier. He moved to Houston from Venezuela in 2019, when he was eleven. \"I didn't speak much English, and I was very shy,\" he remembers. In 2021 he joined the team, but he sat on the bench for a whole season. Two years later, he became a starter. Andrés has played basketball for six years now. \"I've made many mistakes,\" he says, \"but I've learned from all of them.\" Last year the team won the city championship. This year Andrés has already scored more than 200 points. He has also started a free training club for younger kids.", "au": "y350e43b6d0", "img": "u:photo-1519766304817-4f37bda74a26", "q": [{"s": "Andrés has been the captain since September.", "a": "yes"}, {"s": "He moved to Houston in 2015.", "a": "no"}, {"s": "He has played basketball for six years.", "a": "yes"}, {"s": "The team won the national championship.", "a": "no"}]}, "keyq": [{"q": "Have you known your best friend for a long time?", "es": "¿Conoces a tu mejor amigo desde hace mucho tiempo?", "a": "Yes, I have. I've known her since we were in first grade.", "qau": "y3a173315ce", "aau": "y3c68a703fd"}, {"q": "Did you start at your current school in 2022?", "es": "¿Empezaste en tu colegio actual en 2022?", "a": "No, I didn't. I started there in 2020.", "qau": "y32284cc705", "aau": "y379df5c3ba"}, {"q": "Have you watched any good series lately?", "es": "¿Has visto alguna serie buena últimamente?", "a": "Yes, I have. I've watched a great mystery series lately.", "qau": "y3102670922", "aau": "y3805d8dd5a"}]}, "t5p1": {"reading": {"title": "The worst exam day", "text": "Last June, Sam had his final math exam at eight o'clock. He had studied for weeks, and he had set two alarms on his phone. Nothing could go wrong, he thought. But that night his phone fell behind his bed, and the battery died. When he woke up, it was already seven thirty. By the time he got to the bus stop, the bus had already left. He ran to school, but on the way he realized he had left his calculator at home. When he arrived, his friend Ana laughed. The teacher's train was late, so the exam started at nine. Ana lent him her extra calculator, and Sam passed with a great grade.", "au": "y38afbb1f9e", "img": "u:photo-1790939312090-c5edd09de356", "q": [{"s": "Sam had set two alarms.", "a": "yes"}, {"s": "Sam had left his calculator at home.", "a": "yes"}, {"s": "The bus was still at the stop when Sam arrived.", "a": "no"}, {"s": "The exam started at eight.", "a": "no"}]}, "keyq": [{"q": "Had you finished your homework before you came to class today?", "es": "¿Habías terminado tu tarea antes de venir a clase hoy?", "a": "Yes, I had. I had finished it right after lunch.", "qau": "y37a7f83b8b", "aau": "y3e7e1d4f3c"}, {"q": "Had you ever studied English before this course?", "es": "¿Habías estudiado inglés alguna vez antes de este curso?", "a": "Yes, I had. I had studied it at school.", "qau": "y3a6ac504f7", "aau": "y336e8f5ee3"}, {"q": "Had you traveled abroad by the time you were twelve?", "es": "¿Habías viajado al exterior para cuando tenías doce años?", "a": "No, I hadn't. I had never left my country before I was fourteen.", "qau": "y38c44d9bc9", "aau": "y3304aeb721"}]}, "t5p2": {"reading": {"title": "The lost phone", "text": "It all started on our school trip to Washington, D.C. We were visiting a museum, and everyone was taking photos. At first, everything was perfect. Then, all of a sudden, I couldn't find my phone. I realized I had left it on a bench in the dinosaur room. I ran back, but unfortunately, it wasn't there. Meanwhile, my friends were looking for it everywhere. It turned out that a guard had found it and had taken it to the front desk. Eventually, we got there, and the guard gave it back to me. \"Nice lock screen,\" he said, smiling. It was a photo of me with a T. rex!", "au": "y3e472e9f09", "img": "u:photo-1729372463377-ac1adee5090c", "q": [{"s": "We were visiting a museum.", "a": "yes"}, {"s": "I had left my phone on the bus.", "a": "no"}, {"s": "A guard had found the phone.", "a": "yes"}, {"s": "My friends were waiting outside.", "a": "no"}]}, "keyq": [{"q": "Was it raining when you woke up this morning?", "es": "¿Estaba lloviendo cuando te despertaste esta mañana?", "a": "No, it wasn't. The sun was shining, and the birds were singing.", "qau": "y3f1399eaa6", "aau": "y3b370a1239"}, {"q": "Did anything funny happen on your last school trip?", "es": "¿Pasó algo divertido en tu última excursión del colegio?", "a": "Yes, it did. It all started when our teacher got lost in the museum.", "qau": "y3df1d90a23", "aau": "y3f3e70a59e"}, {"q": "Had you ever lost your phone before this year?", "es": "¿Habías perdido tu teléfono alguna vez antes de este año?", "a": "No, I hadn't. Luckily, I had never lost it before.", "qau": "y3495e43b44", "aau": "y3a00fd6586"}]}, "t6p1": {"reading": {"title": "Countdown to exams", "text": "Daniel is fifteen, and exam week is in two weeks. His history teacher, Mr. Ross, said, \"Send me your essay by Monday at noon.\" So Daniel made a plan. On Saturday morning, he studied at the library until one o'clock. In the afternoon, he played soccer with his friends. On Sunday, he finished the essay at night and sent it at 11 p.m. \"Not bad,\" he thought. \"That's before Monday at noon.\" There's also a big concert in the city on May 20th. Daniel wants to go, but tickets go on sale at 9 a.m. sharp next Friday. He'll be ready.", "au": "y3e8c208c40", "img": "u:photo-1776571661811-c311d42634d9", "q": [{"s": "Daniel studied at the library until one o'clock on Saturday.", "a": "yes"}, {"s": "Daniel sent the essay on Monday morning.", "a": "no"}, {"s": "The concert is on May 20th.", "a": "yes"}, {"s": "Tickets go on sale at noon.", "a": "no"}]}, "keyq": [{"q": "Do you usually see your friends on the weekend?", "es": "¿Normalmente ves a tus amigos el fin de semana?", "a": "Yes, I do. We usually meet at the mall on Saturday afternoon.", "qau": "y3ab624d6a3", "aau": "y3ce6d0da89"}, {"q": "Do you stay up until midnight before exams?", "es": "¿Te quedas despierto hasta la medianoche antes de los exámenes?", "a": "No, I don't. I study until ten and then I go to bed.", "qau": "y32fed08d91", "aau": "y365c20f771"}, {"q": "Is your next big exam in two weeks?", "es": "¿Tu próximo examen importante es dentro de dos semanas?", "a": "Yes, it is. It's on Friday, May 9th.", "qau": "y37689b105f", "aau": "y3be7c24655"}]}, "t6p2": {"reading": {"title": "Concert night", "text": "On Saturday, Mia and her best friend went to their first big concert. The doors opened at six, and the show started at eight. \"We have to be there on time,\" Mia said. But while they were riding the train, it stopped in a tunnel for forty minutes! Mia checked the time again and again during the trip. They arrived at 7:55, just in time for the first song. The band played for two hours. During the last song, everyone sang together. At the end of the concert, Mia posted a video, and it got 500 likes within an hour. \"In the end, it was an amazing night,\" she said.", "au": "y3f1a141952", "img": "u:photo-1565035010268-a3816f98589a", "q": [{"s": "The train stopped in a tunnel for forty minutes.", "a": "yes"}, {"s": "Mia and her friend missed the first song.", "a": "no"}, {"s": "The band played for three hours.", "a": "no"}, {"s": "Mia's video got 500 likes within an hour.", "a": "yes"}]}, "keyq": [{"q": "Do you listen to music while you're studying?", "es": "¿Escuchas música mientras estudias?", "a": "Yes, I do. I listen to quiet music while I'm studying.", "qau": "y3895b6a140", "aau": "y3f0ea2c465"}, {"q": "Did you study for more than two hours last night?", "es": "¿Estudiaste durante más de dos horas anoche?", "a": "No, I didn't. I studied for about an hour.", "qau": "y3d2a3fbc2d", "aau": "y39cbbf0d7d"}, {"q": "Do you usually answer messages within an hour?", "es": "¿Normalmente respondes los mensajes en un plazo de una hora?", "a": "Yes, I do. I usually answer within a few minutes.", "qau": "y324cc78d0e", "aau": "y32bc994cf6"}]}, "t7p1": {"reading": {"title": "A school trip to Chicago", "text": "Last month, Camila's class went on a school trip to Chicago. On the plane, she sat next to her best friend. At the airport, a guide was waiting for them at the door. They stayed in a hotel on Michigan Avenue, on the 15th floor. In the morning, they walked along the river and took photos for social media. In the afternoon, they took a boat through the city, under many bridges. Their favorite place was a big park opposite the hotel, near the lake. \"In the elevator, we always laughed and sang,\" Camila says. \"It was an amazing trip!\"", "au": "y3e2c95bd4d", "img": "u:photo-1558638872-3d7081facdc0", "q": [{"s": "Camila sat next to her best friend on the plane.", "a": "yes"}, {"s": "Their hotel rooms were on the 5th floor.", "a": "no"}, {"s": "They walked along the river in the morning.", "a": "yes"}, {"s": "The park was far from the hotel.", "a": "no"}]}, "keyq": [{"q": "Have you ever walked across a famous bridge?", "es": "¿Alguna vez has cruzado un puente famoso a pie?", "a": "Yes, I have. I walked across the Golden Gate Bridge last year.", "qau": "y3c64659cee", "aau": "y3b39ce277b"}, {"q": "Do you sit near the window in class?", "es": "¿Te sientas cerca de la ventana en clase?", "a": "Yes, I do. My desk is near the window, opposite the door.", "qau": "y3efe2722e8", "aau": "y3492026024"}, {"q": "Were you at school at 8 a.m. today?", "es": "¿Estabas en el colegio a las 8 a.m. hoy?", "a": "Yes, I was. I was in my classroom on the third floor.", "qau": "y3638815b67", "aau": "y32d4482b7d"}]}, "t7p2": {"reading": {"title": "Lost in Boston", "text": "Mateo is on a school trip in Boston. He and two friends want to visit a big music store. Mateo asks a woman on the street, \"Excuse me, could you tell me how to get to Newbury Street?\" \"Sure,\" she says. \"Go straight for three blocks and turn right at the intersection. Walk along the park. Newbury Street is at the end, on your left.\" \"Is there a pizza place around here?\" his friend asks. \"Yes, there's one right across from the station, next to the bookstore.\" The boys follow her directions and find the music store on the corner of Newbury and Dartmouth. \"Thanks to her, we didn't get lost!\" Mateo says.", "au": "y3616ba4bcd", "img": "u:photo-1619468129361-605ebea04b44", "q": [{"s": "Mateo is on a school trip in Boston.", "a": "yes"}, {"s": "The woman says to turn left at the intersection.", "a": "no"}, {"s": "The pizza place is right across from the station.", "a": "yes"}, {"s": "The boys got lost.", "a": "no"}]}, "keyq": [{"q": "Is there a good pizza place around here?", "es": "¿Hay una buena pizzería por aquí?", "a": "Yes, there is. It's right across from my school.", "qau": "y3565f6c7d1", "aau": "y34e51a60d9"}, {"q": "Is your house on a busy street?", "es": "¿Tu casa está en una calle con mucho tráfico?", "a": "No, it isn't. It's on a quiet street at the end of the block.", "qau": "y38460c3424", "aau": "y3b0706a093"}, {"q": "Could you tell me how to get to your school from here?", "es": "¿Podrías decirme cómo llegar a tu colegio desde aquí?", "a": "Yes, I can. Go straight for two blocks and turn right.", "qau": "y3a8bc8bfe1", "aau": "y397da4a5ff"}]}, "t8p1": {"reading": {"title": "Two summer camps", "text": "This summer, Sara had to choose between two camps: a soccer camp and a music camp. The music camp was a bit more expensive, but it was much closer to her house. The soccer camp was twice as long as the music camp: four weeks instead of two. Her best friend was going to the soccer camp, so that was far more attractive. But Sara loves her guitar, and the music camp wasn't as crowded as the soccer one. \"Fewer students means more time with the teachers,\" her mom said. In the end, Sara chose the music camp. \"It was a lot more relaxing than I expected,\" she says, \"and just as fun as soccer.\"", "au": "y31d6ffb5c1", "img": "u:photo-1587403062064-b4cf160bde62", "q": [{"s": "The music camp was much closer to Sara's house.", "a": "yes"}, {"s": "The soccer camp was three times as long as the music camp.", "a": "no"}, {"s": "The music camp was more crowded than the soccer camp.", "a": "no"}, {"s": "Sara chose the music camp.", "a": "yes"}]}, "keyq": [{"q": "Is your phone much faster than your old one?", "es": "¿Tu celular es mucho más rápido que el anterior?", "a": "Yes, it is. It's far faster and a bit lighter.", "qau": "y3b2e52f8ab", "aau": "y376b2ea588"}, {"q": "Are online classes as good as face-to-face classes?", "es": "¿Las clases en línea son igual de buenas que las presenciales?", "a": "No, they aren't. For me, they aren't as fun as face-to-face classes.", "qau": "y3f7ae1ed3d", "aau": "y312d468dfe"}, {"q": "Are concert tickets twice as expensive as movie tickets?", "es": "¿Las entradas de conciertos son el doble de caras que las del cine?", "a": "Yes, they are. Some are almost three times as expensive.", "qau": "y3f2c7f604d", "aau": "y3f684871af"}]}, "t8p2": {"reading": {"title": "The best concert of my life", "text": "People always ask me about the best concert I've ever been to. The answer is easy: my favorite band's show last December. My cousin and I waited in line for six hours. The closer it got to eight o'clock, the more excited we became. The stadium got fuller and fuller. When the lights went off, it was the loudest noise I've ever heard. The band played one of the most popular songs of the year first. Not everything was perfect. Our seats were the least comfortable seats in the stadium! But the more we sang, the less we cared. My advice? Buy tickets early. They're getting more and more expensive.", "au": "y3c24375e6b", "img": "u:photo-1533174072545-7a4b6ad7a6c3", "q": [{"s": "The writer went to the concert with a cousin.", "a": "yes"}, {"s": "They waited in line for two hours.", "a": "no"}, {"s": "Their seats were very comfortable.", "a": "no"}, {"s": "Tickets are getting more and more expensive.", "a": "yes"}]}, "keyq": [{"q": "Is your favorite series the best one you've ever watched?", "es": "¿Tu serie favorita es la mejor que has visto?", "a": "Yes, it is. It's by far the best series I've ever watched.", "qau": "y3ce0e07104", "aau": "y3508a6e9a9"}, {"q": "Is English getting easier and easier for you?", "es": "¿El inglés se te hace cada vez más fácil?", "a": "Yes, it is. The more I practice, the easier it gets.", "qau": "y3cc9d1992e", "aau": "y39f2de4b94"}, {"q": "Do you think the sooner you start studying, the better?", "es": "¿Crees que cuanto antes empieces a estudiar, mejor?", "a": "Yes, I do. The sooner I start, the better my grades are.", "qau": "y323f314799", "aau": "y3e4e057ba4"}]}, "t9p1": {"reading": {"title": "My dad's teenage years", "text": "My dad loves telling me about his life as a teenager in the 1990s. Back then, teens didn't use to have smartphones. If he needed to call a friend, he would use a payphone near his school. On Friday nights, he and his friends would go to the video store and choose a movie. They used to argue for an hour about which one to pick! He used to listen to music on a CD player, and he would record songs from the radio. He also used to write letters to a pen pal in Canada. Now he has a smartphone and streams all his music. He no longer buys CDs, but he still keeps his old ones in a box.", "au": "y3225286568", "img": "u:photo-1562072299-8ecc43a8c709", "q": [{"s": "Dad used to use a payphone near his school.", "a": "yes"}, {"s": "Dad used to have a smartphone as a teenager.", "a": "no"}, {"s": "Dad had a pen pal in Mexico.", "a": "no"}, {"s": "Dad still keeps his old CDs in a box.", "a": "yes"}]}, "keyq": [{"q": "Did you use to live in a different city?", "es": "¿Antes vivías en otra ciudad?", "a": "Yes, I did. I used to live in a small town near the coast.", "qau": "y36337684e1", "aau": "y34876b4b7c"}, {"q": "Did you use to play any sports when you were younger?", "es": "¿Practicabas algún deporte cuando eras más pequeño?", "a": "Yes, I did. I used to play basketball every weekend.", "qau": "y3ae79255cd", "aau": "y396d16c8a3"}, {"q": "Did your family use to go on vacation every summer?", "es": "¿Tu familia solía irse de vacaciones cada verano?", "a": "Yes, we did. We would go to the beach every July.", "qau": "y382a164930", "aau": "y30c0569f48"}]}, "t9p2": {"reading": {"title": "My exchange year", "text": "When Sebastián went to Minnesota for an exchange year, he thought English would be the hardest part. He was wrong. His English was fine, but he wasn't used to the cold. In January it was twenty degrees below zero! \"I had to get used to wearing three layers of clothes,\" he says. He also had to get used to small talk. At his high school, everybody talks about the weather. And classes started at 7:30! He was used to starting at eight. Now, after six months, he's getting used to the cold. He even plays ice hockey with his host brother. \"I'm still not used to dinner at six,\" he says, \"but I'll get used to it.\"", "au": "y3b623de44b", "img": "u:photo-1545471977-94cac22e71ed", "q": [{"s": "Sebastián's English was fine.", "a": "yes"}, {"s": "Sebastián was used to the cold.", "a": "no"}, {"s": "Classes at his high school started at eight.", "a": "no"}, {"s": "He plays ice hockey with his host brother.", "a": "yes"}]}, "keyq": [{"q": "Are you used to studying in English?", "es": "¿Estás acostumbrado a estudiar en inglés?", "a": "No, I'm not. But I'm getting used to it little by little.", "qau": "y39b5f4512a", "aau": "y31ca5da1cf"}, {"q": "Have you gotten used to your school schedule?", "es": "¿Ya te acostumbraste a tu horario escolar?", "a": "Yes, I have. I've gotten used to waking up at six.", "qau": "y30c4d1929d", "aau": "y30145443e1"}, {"q": "Would it be hard to get used to life in another country?", "es": "¿Sería difícil acostumbrarte a la vida en otro país?", "a": "Yes, it would. It would be hard to get used to the food.", "qau": "y3af4f7f1e2", "aau": "y3c2aee1c8a"}]}, "t10p1": {"reading": {"title": "The school trip rules", "text": "Our class trip to the national park sounded easy until our teacher read the rules. First, my suitcase was too heavy for the bus, so I had to take some things out. Then my friend Dani wasn't old enough to go on the night hike. You had to be fifteen, and he's only fourteen. He was very upset! At the campsite, there were too many mosquitoes and not enough tents for everyone. On the second day, the river was too cold to swim in, but it was very beautiful. Still, the trip was amazing. Next year Dani will be old enough for the hike, and I'll pack less!", "au": "y3097569bfe", "img": "u:photo-1609788063095-d71bf3c1f01f", "q": [{"s": "The writer's suitcase was too heavy for the bus.", "a": "yes"}, {"s": "Dani was old enough to go on the night hike.", "a": "no"}, {"s": "There were enough tents for everyone.", "a": "no"}, {"s": "The river was too cold to swim in.", "a": "yes"}]}, "keyq": [{"q": "Are you old enough to travel alone by plane?", "es": "¿Tienes edad suficiente para viajar solo en avión?", "a": "No, I'm not. I'm too young to fly alone.", "qau": "y318cdce9cc", "aau": "y3e0aedaffc"}, {"q": "Do you have too much homework this week?", "es": "¿Tienes demasiada tarea esta semana?", "a": "Yes, I do. I have too much homework to go out.", "qau": "y3a558f948b", "aau": "y34b4e6260c"}, {"q": "Is your phone battery good enough to last all day?", "es": "¿La batería de tu celular es lo suficientemente buena para durar todo el día?", "a": "No, it isn't. It's too old to last all day.", "qau": "y39409cfe21", "aau": "y364da5c4e9"}]}, "t10p2": {"reading": {"title": "Dear Grace", "text": "Dear Grace, I'm fifteen and I'm in the school band, but I'm not happy. I play the drums, and I wish I were a singer instead. I wish I had more confidence, but I'm very shy. I also wish I could take singing lessons, but I'm afraid I'm not good enough. Shy in Seattle\n\nDear Shy, you're only fifteen! It isn't too late. Many schools have free singing clubs after class. Start small. Sing for your family or your best friends and see how you feel. Ask your music teacher for advice too. Don't just wish for a different life. Start building it today! Grace", "au": "y3216041412", "img": "u:photo-1597169428801-7c1adf2623bd", "q": [{"s": "The writer plays the drums.", "a": "yes"}, {"s": "The writer is very confident.", "a": "no"}, {"s": "Grace says it's too late to start singing.", "a": "no"}, {"s": "Grace says to sing for family or friends.", "a": "yes"}]}, "keyq": [{"q": "Do you wish you could speak another language?", "es": "¿Te gustaría poder hablar otro idioma?", "a": "Yes, I do. I wish I could speak Korean.", "qau": "y364ed9ddf3", "aau": "y3ecb1b32cb"}, {"q": "Do you wish you had more free time?", "es": "¿Te gustaría tener más tiempo libre?", "a": "Yes, I do. I wish I had more time for my friends.", "qau": "y3dcade9ace", "aau": "y3eb726ea6f"}, {"q": "Do you wish you lived in another city?", "es": "¿Te gustaría vivir en otra ciudad?", "a": "No, I don't. But I wish my city were closer to the beach.", "qau": "y30e6f5a1c3", "aau": "y3223bd0682"}]}, "t11p1": {"reading": {"title": "Movie night shopping", "text": "On Friday, Valeria and her friends planned a movie night at her house. Before going to the supermarket, they checked the kitchen. There wasn't much juice, only half a bottle. \"How many bags of popcorn do we have?\" Diego asked. \"Not many. Maybe two,\" Valeria answered. They needed a lot of things: two bags of chips, six cans of soda, some fruit and a loaf of bread for sandwiches. They didn't need any cheese because Valeria's mom bought some on Thursday. At the store, Diego wanted lots of candy, but they didn't have much money. In the end, they spent twenty dollars. \"How much was the candy?\" Valeria asked. \"Not much,\" Diego smiled.", "au": "y34ff4c95d6", "img": "u:photo-1609980705251-8d7d6266036d", "q": [{"s": "There was a lot of juice at Valeria's house.", "a": "no"}, {"s": "They needed some fruit.", "a": "yes"}, {"s": "They bought cheese at the store.", "a": "no"}, {"s": "They spent twenty dollars.", "a": "yes"}]}, "keyq": [{"q": "Do you spend much time on your phone every day?", "es": "¿Pasas mucho tiempo en tu celular todos los días?", "a": "Yes, I do. I spend a lot of time on my phone.", "qau": "y3cb9700263", "aau": "y35467099bd"}, {"q": "Are there many people in your family?", "es": "¿Hay muchas personas en tu familia?", "a": "No, there aren't. There are only four of us.", "qau": "y3b3a7a0e99", "aau": "y376ffe5a81"}, {"q": "Is there any food you never eat?", "es": "¿Hay alguna comida que nunca comas?", "a": "Yes, there is. I never eat any mushrooms.", "qau": "y344b16128d", "aau": "y339cc33104"}]}, "t11p2": {"reading": {"title": "My exchange trip", "text": "When Andrés got a place in a school exchange program in Canada, he asked his friends for advice. His friend Lina gave him a great piece of advice: \"Don't take a lot of luggage. You'll buy new clothes there.\" So he took only one suitcase. His host family's house had a lot of furniture but not much room, so he shared a bedroom with his host brother. The school gave him some information about clubs, and he joined the soccer team. They had great equipment! Andrés has a lot of experience in soccer, but playing in the snow was a new experience. Every weekend he called his parents with news. \"The news is always good,\" his mom says.", "au": "y31ce534796", "img": "u:photo-1667385914911-5f6f249200b7", "q": [{"s": "Lina gave Andrés a piece of advice.", "a": "yes"}, {"s": "Andrés took three suitcases.", "a": "no"}, {"s": "Andrés had his own bedroom.", "a": "no"}, {"s": "Andrés joined the soccer team.", "a": "yes"}]}, "keyq": [{"q": "Can you give me a piece of advice about exams?", "es": "¿Me puedes dar un consejo sobre los exámenes?", "a": "Yes, I can. Start studying a week before the exam.", "qau": "y36dd033e60", "aau": "y326461c5fd"}, {"q": "Do you usually take much luggage on a trip?", "es": "¿Normalmente llevas mucho equipaje en un viaje?", "a": "No, I don't. I usually take just one backpack.", "qau": "y3f95101306", "aau": "y30e7506392"}, {"q": "Do you have much experience in a sport?", "es": "¿Tienes mucha experiencia en algún deporte?", "a": "Yes, I do. I have a lot of experience in basketball.", "qau": "y3d939c95ac", "aau": "y37c966aa23"}]}, "t12p1": {"reading": {"title": "Two friends, two attitudes", "text": "Camila and Paula are best friends, but they see the world very differently. Last month they both wanted to join the school theater club. Camila said, \"We have a little experience from summer camp, so we have a chance.\" Paula didn't agree. \"We have very little experience, and few students get a place.\" Camila just smiled. \"I know a few people in the club. I'll ask them for tips.\" Paula practiced a lot but had little hope. Both girls went to the audition. Quite a few students tried, but only a few got a role. Camila got a small part, and Paula got the main role! Now, when Paula feels negative, Camila says, \"See? A little hope goes a long way.\"", "au": "y3f768a4ee5", "img": "u:photo-1630050525402-06c617847d27", "q": [{"s": "Both girls wanted to join the theater club.", "a": "yes"}, {"s": "Paula thought they had a good chance.", "a": "no"}, {"s": "Quite a few students tried.", "a": "yes"}, {"s": "Camila got the main role.", "a": "no"}]}, "keyq": [{"q": "Do you have a few close friends at school?", "es": "¿Tienes unos cuantos amigos cercanos en el colegio?", "a": "Yes, I do. I have a few really close friends.", "qau": "y3ef3516b05", "aau": "y3f15d87241"}, {"q": "Do you have much free time during exam week?", "es": "¿Tienes mucho tiempo libre en la semana de exámenes?", "a": "No, I don't. I have very little free time.", "qau": "y3cd6211606", "aau": "y3cf61504b8"}, {"q": "Do you know quite a few songs in English?", "es": "¿Te sabes bastantes canciones en inglés?", "a": "Yes, I do. I know quite a few songs now.", "qau": "y3104699cc9", "aau": "y3b310baf4e"}]}, "t12p2": {"reading": {"title": "How teens use their phones", "text": "A new survey of five thousand teenagers in Denver shows that phone habits are changing. The majority of teens now turn off their phones during homework. They say they have fewer distractions and less stress. A large number of students said they spend less time on social media than last year. But hardly any of them want to stop using their phones completely. Only a few teens want a phone-free weekend. Many students said they have plenty of time for sports and music now. Not many teens play video games every night. \"Teens don't hate their phones,\" says the survey. \"They just want more balance.\"", "au": "y316baa8f87", "img": "u:photo-1455139960217-3de50ca3bc8c", "q": [{"s": "The survey was about phone habits.", "a": "yes"}, {"s": "The majority of teens use their phones during homework.", "a": "no"}, {"s": "Hardly any teens want to stop using their phones completely.", "a": "yes"}, {"s": "A large number of teens want a phone-free weekend.", "a": "no"}]}, "keyq": [{"q": "Do you spend less time on social media than before?", "es": "¿Pasas menos tiempo en redes sociales que antes?", "a": "Yes, I do. I spend much less time on it now.", "qau": "y340264f056", "aau": "y30737d04c2"}, {"q": "Are there fewer students in your school this year?", "es": "¿Hay menos estudiantes en tu colegio este año?", "a": "No, there aren't. There are plenty of new students.", "qau": "y32cc9a818d", "aau": "y3e1d7061de"}, {"q": "Do you have plenty of time to relax on weekends?", "es": "¿Tienes tiempo de sobra para descansar los fines de semana?", "a": "No, I don't. I have hardly any free time.", "qau": "y3dec2f536d", "aau": "y3a46514a27"}]}, "t13p1": {"reading": {"title": "Despite everything", "text": "Martín is sixteen and lives in Chicago. Last year he joined the school band, although he couldn't play any instrument. His friends thought he was crazy. Despite his busy schedule, he practiced the guitar every night. His parents supported him, but they preferred him to use headphones! In October he broke his finger playing basketball. In spite of the injury, Martín didn't give up. He learned the songs by listening to them. However, the hardest moment came on concert night. Even though he was very nervous, he walked on stage. Then he saw his little sister with a sign: \"Go, Martín!\" \"I made some mistakes,\" he says, \"but I played despite everything.\"", "au": "y3e33a09f0e", "img": "u:photo-1735157784070-2e9648c07d15", "q": [{"s": "Martín could play the guitar before he joined the band.", "a": "no"}, {"s": "He practiced every night.", "a": "yes"}, {"s": "He broke his finger playing soccer.", "a": "no"}, {"s": "He was nervous on concert night.", "a": "yes"}]}, "keyq": [{"q": "Do you study even though you don't enjoy it?", "es": "¿Estudias aun cuando no lo disfrutas?", "a": "Yes, I do. I study math even though I don't enjoy it.", "qau": "y36b0c7c547", "aau": "y3b75f06151"}, {"q": "Do you go out with friends despite having exams?", "es": "¿Sales con amigos a pesar de tener exámenes?", "a": "No, I don't. Although I want to, I stay home and study.", "qau": "y31becbfe25", "aau": "y3e9f3c7318"}, {"q": "Is your city beautiful?", "es": "¿Tu ciudad es bonita?", "a": "Yes, it is. However, the traffic is terrible.", "qau": "y3c514b56b5", "aau": "y322490c172"}]}, "t13p2": {"reading": {"title": "Should our school ban phones?", "text": "The principal of a high school in Raleigh asked the student council a question: should the school ban phones during the day? The students wrote a list. First, they looked at the advantages. Without phones, students pay more attention in class. As a result, their grades could go up. In addition, there could be fewer distractions. Besides, students could talk more during breaks. On the other hand, the council found some problems. For example, many students use their phones for homework apps. Also, parents want to contact their kids in emergencies. That's why the council suggested a middle option: phones in lockers during classes, but free at lunch. To sum up, they said balance is the key.", "au": "y3efaa24323", "img": "u:photo-1647342015696-9e9a7563c3b9", "q": [{"s": "The principal asked about banning phones.", "a": "yes"}, {"s": "The council said phones should be free all day.", "a": "no"}, {"s": "Some students use their phones for homework apps.", "a": "yes"}, {"s": "Parents don't want to contact their kids.", "a": "no"}]}, "keyq": [{"q": "Is learning English useful?", "es": "¿Es útil aprender inglés?", "a": "Yes, it is. In addition, it helps you understand songs and series.", "qau": "y30a62ef462", "aau": "y31009175e7"}, {"q": "Do you feel tired when you stay up late?", "es": "¿Te sientes cansado cuando te acuestas tarde?", "a": "Yes, I do. As a result, I can't concentrate in class.", "qau": "y3e2313643c", "aau": "y354213dde0"}, {"q": "Do you study English because you want to travel?", "es": "¿Estudias inglés porque quieres viajar?", "a": "Yes, I do. I want to travel, so I study every day.", "qau": "y3e5f898c41", "aau": "y3c0dbf663e"}]}}};
